import { useState, useEffect } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import {
  Music,
  Minus,
  Plus,
  Upload,
  Download,
  ChevronDown,
  Settings2,
  HelpCircle,
  Sliders,
  BookOpen,
  RotateCcw,
  User
} from 'lucide-react';
import {
  THEMES,
  getThemeBg
} from '../constants/midiConstants';

export default function HeaderBar({
  currentTheme,
  setCurrentTheme,
  barCount,
  setBarCount,
  zoom,
  setZoom,
  fileInputRef,
  exportMidi,
  exportWav,
  currentInstrument,
  isInstrumentMenuOpen,
  setIsInstrumentMenuOpen,
  isFxOpen,
  setIsFxOpen,
  openIntro,
  isDashboardOpen,
  setIsDashboardOpen,
  openGuide,
  openManual,
  openProfile,
  currentUser
}) {
  const [isThemeMenuOpen, setIsThemeMenuOpen] = useState(false);
  const [isFileMenuOpen, setIsFileMenuOpen] = useState(false);

  const [time, setTime] = useState(new Date());

  useEffect(() => {
    const timer = setInterval(() => setTime(new Date()), 1000);
    return () => clearInterval(timer);
  }, []);

  const formattedTime = time.toLocaleTimeString('en-US', { 
    hour12: false, 
    hour: '2-digit', 
    minute: '2-digit', 
    second: '2-digit' 
  });
  const formattedDate = time.toLocaleDateString('en-US', { 
    month: 'short', 
    day: '2-digit' 
  }).toUpperCase();

  const dropdownStyle = {
    background: 'rgba(8,8,12,0.96)',
    backdropFilter: 'blur(40px) saturate(140%)',
    boxShadow: `0 24px 64px rgba(0,0,0,0.85), inset 0 1px 0 0 rgba(255,255,255,0.08), 0 0 0 1px rgba(255,255,255,0.06)`
  };

  return (
    <header className="h-16 bg-black/45 backdrop-blur-3xl border-b border-white/[0.06] flex items-center justify-center px-4 z-50 shrink-0 relative gap-6 shadow-[0_4px_30px_rgba(0,0,0,0.5)]">
      {/* Top accent neon line */}
      <div 
        className="absolute top-0 left-0 right-0 h-[2px]"
        style={{
          background: 'linear-gradient(90deg, #ff3366, #ff9f43, #2ebd59, #00f0ff, #0066ff, #ff3366)',
          backgroundSize: '300% 300%',
          animation: 'rainbowBorder 8s linear infinite',
          boxShadow: '0 0 14px rgba(0, 240, 255, 0.4)'
        }}
      />

      <div className="w-full max-w-[1600px] px-16 flex items-center justify-between gap-6 header-inner">
        {/* LEFT: Logo + Controls */}
        <div className="flex items-center gap-6">
        {/* Redesigned Logo Emblem */}
        <div className="flex items-center gap-4 cursor-pointer group mr-3 select-none" onClick={openIntro}>
          <div 
            className="w-12 h-12 rounded-2xl flex items-center justify-center transition-all duration-300 group-hover:scale-105 active:scale-95 relative overflow-hidden shadow-[0_0_30px_rgba(255,255,255,0.08)] border border-white/10"
            style={{
              background: 'linear-gradient(135deg, rgba(255,255,255,0.1), rgba(255,255,255,0.03))',
            }}
          >
            {/* Glow behind the icon matching current theme */}
            <div 
              className="absolute inset-0.5 rounded-[14px] opacity-40 blur-[4px] transition-all duration-500 group-hover:opacity-60"
              style={{ background: getThemeBg(currentTheme) }}
            />

            {/* Theme color gradient background */}
            <div 
              className="absolute inset-1 rounded-[12px] opacity-90 transition-all duration-500 group-hover:rotate-12"
              style={{ background: getThemeBg(currentTheme) }}
            />

            {/* Glass diagonal glossy sheen reflection */}
            <div className="absolute inset-0 bg-gradient-to-tr from-transparent via-white/20 to-transparent translate-x-[-100%] group-hover:translate-x-[100%] transition-transform duration-1000 ease-out" />

            <svg viewBox="0 0 24 24" fill="none" className="w-6 h-6 text-white relative z-10 drop-shadow-md group-hover:rotate-12 transition-transform duration-300" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round">
              <path d="M9 18V5l12-2v13" />
              <circle cx="6" cy="18" r="3" fill="currentColor" />
              <circle cx="18" cy="16" r="3" fill="currentColor" />
              <path d="M3 10c1-1 3-1 4 0" opacity="0.7" strokeWidth="1.5" />
              <path d="M14 6c1-1 3-1 4 0" opacity="0.7" strokeWidth="1.5" />
            </svg>
          </div>
          <div className="hidden xl:flex flex-col">
            <span className="text-[16px] font-black tracking-[0.25em] uppercase leading-none text-white drop-shadow-md">
              MELODY <span className="bg-gradient-to-r from-[#ff3366] via-[#ff9f43] to-[#00f0ff] bg-clip-text text-transparent filter drop-shadow-[0_0_10px_rgba(0,240,255,0.3)] font-black">SKETCHER</span>
            </span>
            <div className="flex items-center gap-1.5 mt-1.5">
              <span className="text-[8px] font-black text-slate-400 uppercase tracking-[0.4em]">STUDIO</span>
              <span className="text-[7px] font-extrabold text-white/80 bg-white/10 px-1.5 py-0.5 rounded-md border border-white/5 shadow-sm leading-none">PRO</span>
            </div>
          </div>
        </div>

        <div className="w-px h-10 bg-white/[0.08]" />

        {/* Bar Length */}
        <div className="flex items-center gap-1.5 bg-white/[0.03] rounded-2xl px-2 py-1.5 border border-white/[0.06] shadow-md">
          <button
            onClick={() => setBarCount(Math.max(1, barCount - 1))}
            className="w-8 h-8 rounded-lg hover:bg-white/10 flex items-center justify-center transition-all text-slate-300 hover:text-white cursor-pointer active:scale-90"
          >
            <Minus className="w-4 h-4" />
          </button>
          <div className="px-2 py-0.5 text-center select-none min-w-[60px]">
            <span className="text-[9px] font-bold text-slate-400 uppercase tracking-widest block leading-none">BARS</span>
            <span className="text-[13px] font-black text-white tabular-nums block mt-0.5">{barCount}</span>
          </div>
          <button
            onClick={() => setBarCount(barCount + 1)}
            className="w-8 h-8 rounded-lg hover:bg-white/10 flex items-center justify-center transition-all text-slate-300 hover:text-white cursor-pointer active:scale-90"
          >
            <Plus className="w-4 h-4" />
          </button>
        </div>

        {/* Zoom */}
        <div className="flex items-center gap-1.5 bg-white/[0.03] rounded-2xl px-2 py-1.5 border border-white/[0.06] shadow-md">
          <button
            onClick={() => setZoom(Math.max(0.2, zoom - 0.1))}
            className="w-8 h-8 rounded-lg hover:bg-white/10 flex items-center justify-center transition-all text-slate-300 hover:text-white cursor-pointer active:scale-90"
          >
            <Minus className="w-4 h-4" />
          </button>
          <button
            onClick={() => setZoom(1)}
            className="group flex flex-col items-center justify-center px-2 py-0.5 select-none min-w-[60px] cursor-pointer hover:bg-white/10 rounded-lg transition-all active:scale-95"
            title="Reset Zoom"
          >
            <div className="flex items-center gap-1">
              <span className="text-[9px] font-bold text-slate-400 uppercase tracking-widest block leading-none group-hover:text-white transition-colors">ZOOM</span>
              <RotateCcw className="w-2.5 h-2.5 text-slate-400 group-hover:text-white transition-colors" />
            </div>
            <span className="text-[13px] font-black text-white tabular-nums block mt-0.5">{Math.round(zoom * 100)}%</span>
          </button>
          <button
            onClick={() => setZoom(Math.min(4, zoom + 0.1))}
            className="w-8 h-8 rounded-lg hover:bg-white/10 flex items-center justify-center transition-all text-slate-300 hover:text-white cursor-pointer active:scale-90"
          >
            <Plus className="w-4 h-4" />
          </button>
        </div>
      </div>

      {/* RIGHT: Actions */}
      <div className="flex items-center gap-4">
        {/* File Menu */}
        <div className="relative">
          <button
            onClick={() => { setIsFileMenuOpen(!isFileMenuOpen); setIsThemeMenuOpen(false); }}
            className="flex items-center gap-2 px-5 py-2.5 rounded-2xl glass-gloss transition-all text-[11px] font-black uppercase tracking-wider text-slate-200 hover:text-white cursor-pointer hover:scale-[1.02] active:scale-95"
          >
            <Download className="w-4 h-4" />
            <span className="hidden sm:inline">File</span>
            <ChevronDown className={`w-4 h-4 transition-transform ${isFileMenuOpen ? 'rotate-180' : ''}`} />
          </button>
          <AnimatePresence>
            {isFileMenuOpen && (
              <motion.div
                initial={{ opacity: 0, y: 6, scale: 0.97 }}
                animate={{ opacity: 1, y: 0, scale: 1 }}
                exit={{ opacity: 0, y: 6, scale: 0.97 }}
                transition={{ duration: 0.15 }}
                className="absolute right-0 top-14 rounded-2xl p-2 z-50 w-48"
                style={dropdownStyle}
              >
                <button
                  onClick={() => { fileInputRef.current.click(); setIsFileMenuOpen(false); }}
                  className="flex items-center gap-3 w-full px-3 py-2.5 rounded-xl hover:bg-white/10 transition-all text-[11px] font-bold uppercase tracking-wider text-slate-200 cursor-pointer"
                >
                  <Upload className="w-4 h-4 text-slate-400" /> Import MIDI
                </button>
                <button
                  onClick={() => { exportMidi(); setIsFileMenuOpen(false); }}
                  className="flex items-center gap-3 w-full px-3 py-2.5 rounded-xl hover:bg-white/10 transition-all text-[11px] font-bold uppercase tracking-wider text-slate-200 cursor-pointer"
                >
                  <Download className="w-4 h-4 text-slate-400" /> Export MIDI (.mid)
                </button>
                <div className="h-px bg-white/10 my-1 mx-2" />
                <button
                  onClick={() => { exportWav(); setIsFileMenuOpen(false); }}
                  className="flex items-center gap-3 w-full px-3 py-2.5 rounded-xl hover:bg-white/10 transition-all text-[11px] font-bold uppercase tracking-wider text-slate-200 cursor-pointer"
                >
                  <Music className="w-4 h-4 text-indigo-400" /> Render WAV
                </button>
              </motion.div>
            )}
          </AnimatePresence>
        </div>



        {/* Instrument Selector */}
        <button
          onClick={() => setIsInstrumentMenuOpen(!isInstrumentMenuOpen)}
          className="flex items-center gap-3 px-5 py-2.5 rounded-2xl glass-gloss transition-all cursor-pointer group hover:scale-[1.02] active:scale-95"
        >
          <span className="group-hover:scale-110 transition-transform flex items-center justify-center">
            {currentInstrument.icon && typeof currentInstrument.icon !== 'string' ? (
              <currentInstrument.icon size={22} strokeWidth={1.5} />
            ) : (
              <span className="text-xl">{currentInstrument.icon}</span>
            )}
          </span>
          <div className="hidden lg:flex flex-col text-left select-none">
            <span className="text-[9px] font-bold uppercase tracking-widest text-slate-400 leading-none">INSTRUMENT</span>
            <span className="text-[12px] font-bold text-white mt-1 leading-none">{currentInstrument.name}</span>
          </div>
          <ChevronDown className={`w-4 h-4 text-slate-400 transition-transform ${isInstrumentMenuOpen ? 'rotate-180' : ''}`} />
        </button>

        {/* FX Toggle */}
        <button
          onClick={() => setIsFxOpen(!isFxOpen)}
          className={`w-11 h-11 rounded-2xl flex items-center justify-center transition-all duration-300 relative group cursor-pointer hover:scale-[1.02] active:scale-95 ${
            isFxOpen 
              ? 'bg-white text-black border-white shadow-[0_0_20px_rgba(255,255,255,0.25)]' 
              : 'glass-gloss text-slate-300 hover:text-white'
          }`}
          title="Master FX"
        >
          <Settings2 className="w-5 h-5 group-hover:rotate-45 transition-transform duration-500" />
          {isFxOpen && <div className="absolute -top-1 -right-1 w-2.5 h-2.5 rounded-full bg-emerald-400 animate-pulse" />}
        </button>

        {/* Studio Utilities Dashboard Toggle */}
        <button
          onClick={() => { setIsDashboardOpen(!isDashboardOpen); setIsFxOpen(false); }}
          className={`w-11 h-11 rounded-2xl flex items-center justify-center transition-all duration-300 relative group cursor-pointer hover:scale-[1.02] active:scale-95 ${
            isDashboardOpen 
              ? 'bg-white text-black border-white shadow-[0_0_20px_rgba(255,255,255,0.25)]' 
              : 'glass-gloss text-slate-300 hover:text-white'
          }`}
          title="Studio Dashboard"
        >
          <Sliders className="w-5 h-5 group-hover:rotate-12 transition-transform duration-300" />
          {isDashboardOpen && <div className="absolute -top-1 -right-1 w-2.5 h-2.5 rounded-full bg-[#00f0ff] animate-pulse" />}
        </button>

        {/* Help */}
        <button
          onClick={openGuide}
          className="w-11 h-11 rounded-2xl flex items-center justify-center glass-gloss text-slate-300 hover:text-white transition-all cursor-pointer hover:scale-[1.02] active:scale-95"
          title="Studio Guide"
        >
          <HelpCircle className="w-5 h-5" />
        </button>

        {/* User Manual */}
        <button
          onClick={openManual}
          className="w-11 h-11 rounded-2xl flex items-center justify-center glass-gloss text-slate-300 hover:text-white transition-all cursor-pointer hover:scale-[1.02] active:scale-95"
          title="User Manual"
        >
          <BookOpen className="w-5 h-5" />
        </button>

        {/* User Profile Button */}
        <button
          onClick={openProfile}
          className="px-4 h-11 rounded-2xl flex items-center justify-center gap-2 glass-gloss text-slate-300 hover:text-white border border-white/[0.06] hover:border-white/15 transition-all cursor-pointer hover:scale-[1.02] active:scale-95 group relative overflow-hidden"
          title="User Profile & Cloud Library"
        >
          {currentUser ? (
            <>
              <span className="text-sm shrink-0">{currentUser.avatar}</span>
              <span className="text-[10.5px] font-black uppercase tracking-wider text-slate-200 block max-w-[90px] truncate leading-none">
                {currentUser.username}
              </span>
              <div className="absolute top-0 right-0 w-2 h-2 rounded-full bg-cyan-400 m-1 shadow-[0_0_8px_#00f0ff]" />
            </>
          ) : (
            <>
              <User className="w-4 h-4 group-hover:text-cyan-400 transition-colors" />
              <span className="text-[10px] font-black uppercase tracking-wider text-slate-200 hidden md:inline">
                Sign In
              </span>
            </>
          )}
        </button>

        {/* Futuristic Studio Clock & Date */}
        <div className="flex items-center gap-3 px-4 py-2.5 rounded-2xl glass-dark border border-white/[0.08] shadow-[inset_0_1px_8px_rgba(0,240,255,0.06)] relative overflow-hidden group select-none">
          <div className="absolute inset-0 bg-gradient-to-tr from-transparent via-white/5 to-transparent translate-x-[-100%] group-hover:translate-x-[100%] transition-transform duration-1000 ease-out" />
          {/* Pulsating status dot matching theme */}
          <div 
            className="w-1.5 h-1.5 rounded-full animate-pulse shrink-0" 
            style={{ 
              backgroundColor: currentTheme.color,
              boxShadow: `0 0 10px ${currentTheme.color}`
            }} 
          />
          <div className="flex items-baseline gap-2 tabular-nums leading-none">
            <span className="text-[13px] font-black text-slate-100">{formattedTime}</span>
            <span className="text-[7.5px] font-black text-slate-500 uppercase tracking-widest">{formattedDate}</span>
          </div>
        </div>
      </div>
      </div>
    </header>
  );
}

import { useState } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { X, Search, Sparkles, Music } from 'lucide-react';
import { INSTRUMENTS } from '../constants/midiConstants';

const TABS = [
  { id: 'all', name: 'All' },
  { id: 'keys', name: 'Keys & Organs' },
  { id: 'strings', name: 'Strings & Brass' },
  { id: 'guitars', name: 'Guitars & Basses' },
  { id: 'synths', name: 'Synths & Pads' },
  { id: 'drums', name: 'Drums & Perc' },
  { id: 'fx', name: 'FX & Ethnic' }
];

const FLAGSHIP_IDS = [
  'acoustic-piano', 'electric-piano', 'lofi-keys', 'marimba', 'org', 
  'nylon-guitar', 'electric-guitar', 'slap-bass', 'synth-bass', '808-bass', 
  'strings', 'choral', 'brass', 'flute', 'pulse', 'synth-lead', 'fm', 
  'synth-pad', 'bells', 'drum-kit'
];

const getTabIdForInstrument = (inst) => {
  const cat = inst.category;
  if (cat === 'Pianos' || cat === 'Organs') return 'keys';
  if (cat === 'Guitars' || cat === 'Basses') return 'guitars';
  if (cat === 'Strings' || cat === 'Ensembles' || cat === 'Brass' || cat === 'Reeds' || cat === 'Pipes') return 'strings';
  if (cat === 'Leads' || cat === 'Pads') return 'synths';
  if (cat === 'Percussion' || cat === 'Percussive' || cat === 'Drums') return 'drums';
  return 'fx'; // Synth FX, Ethnic, Sound Effects
};

export default function InstrumentSelector({
  currentInstrument,
  setCurrentInstrument,
  currentTheme,
  closeMenu
}) {
  const [activeTab, setActiveTab] = useState('all');
  const [searchQuery, setSearchQuery] = useState('');

  // First filter by tab and search query
  const matchesSearch = (inst) => {
    const query = searchQuery.toLowerCase().trim();
    if (!query) return true;
    return inst.name.toLowerCase().includes(query) || inst.category.toLowerCase().includes(query);
  };

  const baseFiltered = INSTRUMENTS.filter(inst => {
    const matchesTab = activeTab === 'all' || getTabIdForInstrument(inst) === activeTab;
    return matchesTab && matchesSearch(inst);
  });

  // Segmentize into Flagship and Classic MIDI
  const flagshipInstruments = baseFiltered.filter(inst => FLAGSHIP_IDS.includes(inst.id));
  const classicInstruments = baseFiltered.filter(inst => !FLAGSHIP_IDS.includes(inst.id));

  return (
    <motion.div 
      initial={{ y: -30, opacity: 0, scale: 0.97 }}
      animate={{ y: 0, opacity: 1, scale: 1 }}
      exit={{ y: -30, opacity: 0, scale: 0.97 }}
      transition={{ type: 'spring', stiffness: 300, damping: 28 }}
      className="absolute left-1/2 -translate-x-1/2 top-24 w-[900px] max-w-[95vw] z-50 rounded-[32px] overflow-hidden border"
      style={{
        background: 'rgba(5, 5, 8, 0.88)',
        backdropFilter: 'blur(40px) saturate(240%)',
        borderColor: 'rgba(255,255,255,0.08)',
        boxShadow: `0 40px 100px rgba(0,0,0,0.95), inset 0 1px 0 0 rgba(255,255,255,0.15), inset -2px 0 8px rgba(0,240,255,0.15), inset 2px 0 8px rgba(46,255,147,0.15), 0 0 40px -10px ${currentTheme.color}30`
      }}
    >
      {/* Header */}
      <div className="flex flex-col sm:flex-row items-start sm:items-center justify-between px-10 pt-8 pb-4 gap-4">
        <div>
          <h4 className="text-[14px] font-black uppercase tracking-[0.25em]" style={{ color: currentTheme.color, textShadow: `0 0 12px ${currentTheme.color}80` }}>
            Instrument Library
          </h4>
          <span className="text-[10px] text-slate-400 font-bold uppercase tracking-widest mt-1 block">
            Configure voicing for active track ({baseFiltered.length} of {INSTRUMENTS.length} items)
          </span>
        </div>

        {/* Live Search Input */}
        <div className="relative w-full sm:w-64">
          <span className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400">
            <Search className="w-4 h-4" />
          </span>
          <input
            type="text"
            placeholder="Search all 129 instruments..."
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
            className="w-full pl-11 pr-10 py-2.5 rounded-2xl glass-gloss text-[11px] font-extrabold tracking-wide text-white placeholder-slate-400 focus:outline-none focus:ring-1 focus:ring-slate-500 border border-white/[0.05]"
          />
          {searchQuery && (
            <button 
              onClick={() => setSearchQuery('')}
              className="absolute right-3 top-1/2 -translate-y-1/2 text-slate-400 hover:text-white cursor-pointer"
            >
              <X className="w-3.5 h-3.5" />
            </button>
          )}
        </div>

        <button 
          onClick={closeMenu} 
          className="absolute sm:relative right-6 sm:right-0 top-6 sm:top-0 w-10 h-10 rounded-2xl glass-gloss flex items-center justify-center transition-all text-slate-400 hover:text-white cursor-pointer active:scale-90"
        >
          <X className="w-5 h-5" />
        </button>
      </div>

      {/* Category Tabs */}
      <div className="flex items-center gap-1.5 px-8 pb-4 overflow-x-auto scrollbar-none border-b border-white/[0.04]">
        {TABS.map(tab => (
          <button
            key={tab.id}
            onClick={() => setActiveTab(tab.id)}
            className={`px-4 py-2.5 rounded-xl text-[9px] font-black uppercase tracking-widest transition-all duration-200 cursor-pointer whitespace-nowrap border shadow-sm hover:scale-[1.02] active:scale-95
              ${activeTab !== tab.id 
                ? 'glass-gloss text-slate-400 hover:text-white' 
                : ''
              }`}
            style={{
              background: activeTab === tab.id ? `linear-gradient(135deg, ${currentTheme.color}, #6366f1)` : '',
              color: activeTab === tab.id ? '#ffffff' : '',
              borderColor: activeTab === tab.id ? 'transparent' : 'rgba(255, 255, 255, 0.05)',
              boxShadow: activeTab === tab.id ? `0 0 15px ${currentTheme.color}40` : ''
            }}
          >
            {tab.name}
          </button>
        ))}
      </div>

      {/* Scrollable Container with Segments */}
      <div className="px-8 py-6 max-h-[52vh] overflow-y-auto scrollbar-studio flex flex-col gap-6">

        {/* SECTION 1: Flagship Studio Sounds */}
        {flagshipInstruments.length > 0 && (
          <div>
            <div className="flex items-center gap-2 mb-3.5 px-1">
              <Sparkles className="w-4 h-4 text-amber-400 animate-pulse" />
              <h5 className="text-[10px] font-black uppercase tracking-[0.2em] text-slate-300">
                Flagship Studio Sounds
              </h5>
            </div>

            <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 gap-3">
              {flagshipInstruments.map(inst => {
                const isSelected = currentInstrument.id === inst.id;
                return (
                  <button
                    key={inst.id}
                    onClick={() => { setCurrentInstrument(inst); closeMenu(); }}
                    className={`flex items-center p-4 rounded-2xl transition-all duration-300 gap-4 group relative text-left cursor-pointer hover:scale-[1.02] active:scale-95 border
                      ${isSelected 
                        ? 'bg-white/[0.08] shadow-[0_4px_24px_rgba(0,0,0,0.4)]' 
                        : 'glass-gloss'
                      }
                    `}
                    style={{
                      borderColor: isSelected ? currentTheme.color : 'rgba(255, 255, 255, 0.08)',
                      boxShadow: isSelected ? `0 0 15px ${currentTheme.color}30, inset 0 1px 0 0 rgba(255,255,255,0.08)` : ''
                    }}
                  >
                    {!isSelected && (
                      <div className="absolute inset-0 bg-gradient-to-tr from-transparent via-white/5 to-transparent translate-x-[-100%] group-hover:translate-x-[100%] transition-transform duration-1000 ease-out pointer-events-none" />
                    )}

                    <div 
                      className={`transition-transform duration-300 group-hover:scale-110 ${isSelected ? '' : 'opacity-85 group-hover:opacity-100'}`}
                      style={{ color: isSelected ? currentTheme.color : '#ffffff' }}
                    >
                      {inst.icon && typeof inst.icon !== 'string' ? (
                        <inst.icon size={28} strokeWidth={1.5} />
                      ) : (
                        <span className="text-3xl">{inst.icon}</span>
                      )}
                    </div>

                    <div className="min-w-0">
                      <div className="flex items-center gap-2">
                        <p 
                          className="text-[13px] font-black uppercase tracking-wider leading-tight truncate text-slate-100"
                          style={{ textShadow: isSelected ? `0 0 10px ${currentTheme.color}50` : 'none' }}
                        >
                          {inst.name}
                        </p>
                        <span className="px-1.5 py-0.5 rounded text-[8px] font-black tracking-widest uppercase bg-white/10 text-slate-300">
                          HD
                        </span>
                      </div>
                      <p className="text-[10px] font-extrabold tracking-widest uppercase mt-1 text-slate-400">
                        {inst.category}
                      </p>
                    </div>

                    {isSelected && (
                      <div 
                        className="absolute right-5 w-2 h-2 rounded-full" 
                        style={{ 
                          backgroundColor: currentTheme.color,
                          boxShadow: `0 0 8px ${currentTheme.color}` 
                        }} 
                      />
                    )}
                  </button>
                );
              })}
            </div>
          </div>
        )}

        {/* SECTION 2: Classic General MIDI Voices */}
        {classicInstruments.length > 0 && (
          <div>
            <div className="flex items-center gap-2 mb-3.5 px-1">
              <Music className="w-4 h-4 text-slate-400" />
              <h5 className="text-[10px] font-black uppercase tracking-[0.2em] text-slate-400">
                Classic MIDI Library
              </h5>
            </div>

            <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 gap-3">
              {classicInstruments.map(inst => {
                const isSelected = currentInstrument.id === inst.id;
                return (
                  <button
                    key={inst.id}
                    onClick={() => { setCurrentInstrument(inst); closeMenu(); }}
                    className={`flex items-center p-3.5 rounded-2xl transition-all duration-300 gap-4 group relative text-left cursor-pointer hover:scale-[1.02] active:scale-95 border
                      ${isSelected 
                        ? 'bg-white/[0.05] shadow-[0_4px_16px_rgba(0,0,0,0.3)]' 
                        : 'glass-gloss opacity-80 hover:opacity-100'
                      }
                    `}
                    style={{
                      borderColor: isSelected ? currentTheme.color : 'rgba(255,255,255,0.04)',
                      boxShadow: isSelected ? `0 0 10px ${currentTheme.color}20, inset 0 1px 0 0 rgba(255,255,255,0.05)` : ''
                    }}
                  >
                    <div 
                      className={`transition-transform duration-300 group-hover:scale-105 ${isSelected ? '' : 'opacity-60 group-hover:opacity-100'}`}
                      style={{ color: isSelected ? currentTheme.color : '#cbd5e1' }}
                    >
                      {inst.icon && typeof inst.icon !== 'string' ? (
                        <inst.icon size={22} strokeWidth={1.5} />
                      ) : (
                        <span className="text-2xl">{inst.icon}</span>
                      )}
                    </div>

                    <div className="min-w-0">
                      <p 
                        className="text-[12px] font-bold uppercase tracking-wider leading-tight truncate text-slate-200"
                        style={{ textShadow: isSelected ? `0 0 8px ${currentTheme.color}40` : 'none' }}
                      >
                        {inst.name}
                      </p>
                      <p className="text-[9px] font-bold tracking-widest uppercase mt-0.5 text-slate-500">
                        {inst.category}
                      </p>
                    </div>

                    {isSelected && (
                      <div 
                        className="absolute right-4 w-1.5 h-1.5 rounded-full" 
                        style={{ 
                          backgroundColor: currentTheme.color,
                          boxShadow: `0 0 6px ${currentTheme.color}` 
                        }} 
                      />
                    )}
                  </button>
                );
              })}
            </div>
          </div>
        )}

        {/* Empty State */}
        {baseFiltered.length === 0 && (
          <div className="flex flex-col items-center justify-center py-12 text-slate-500 gap-3">
            <Search className="w-8 h-8 opacity-40 animate-bounce" />
            <p className="text-[12px] font-black uppercase tracking-widest text-slate-400">
              No instruments match your search
            </p>
            <button 
              onClick={() => { setSearchQuery(''); setActiveTab('all'); }}
              className="px-4 py-2 mt-2 rounded-xl text-[9px] font-black uppercase tracking-widest bg-white/10 hover:bg-white/20 text-white cursor-pointer active:scale-95 transition-all"
            >
              Reset Filters
            </button>
          </div>
        )}

      </div>
    </motion.div>
  );
}

import { useState, useEffect, useRef, useCallback } from 'react';
import * as Tone from 'tone';
import { motion, AnimatePresence } from 'framer-motion';

import { 
  GRID_SUBDIVISIONS,
  TICKS_PER_BEAT,
  ALL_NOTES,
  INSTRUMENTS,
  THEMES,
  TRACK_COLORS,
  KEY_TO_NOTE,
  BASE_BEAT_WIDTH,
  BASE_ROW_HEIGHT
} from '../constants/midiConstants';

import MasterFxPanel from './MasterFxPanel';
import MixerConsole from './MixerConsole';
import InstrumentSelector from './InstrumentSelector';
import HeaderBar from './HeaderBar';
import TrackTabs from './TrackTabs';
import PianoKeys from './PianoKeys';
import TransportBar from './TransportBar';
import IntroOverlay from './IntroOverlay';
import SequencerCanvas from './SequencerCanvas';
import StudioDashboard from './StudioDashboard';
import InteractiveGuide from './InteractiveGuide';
import UserManual from './UserManual';
import UserProfileModal from './UserProfileModal';
import { ToastContainer, useToast } from './Toast';

import useAudioEngine from '../hooks/useAudioEngine';
import useAudioExport from '../hooks/useAudioExport';
import useMidiKeyboard from '../hooks/useMidiKeyboard';
import useGamepadController from '../hooks/useGamepadController';

export default function MelodySketcher() {
  // In-app toast notification system
  const { toasts, showToast, dismissToast } = useToast();

  // Safe synchronous load of saved workspace
  const savedWorkspace = (() => {
    try {
      const saved = localStorage.getItem('melody_sketcher_workspace');
      return saved ? JSON.parse(saved) : null;
    } catch {
      return null;
    }
  })();

  const [customThemes, setCustomThemes] = useState([]);
  const [currentTheme, setCurrentTheme] = useState(() => THEMES[0]);
  const [isPlaying, setIsPlaying] = useState(false);
  const [isRecording, setIsRecording] = useState(false);
  const [bpm, setBpm] = useState(120);
  const [masterVolume, setMasterVolume] = useState(0);
  const [barCount, setBarCount] = useState(8);
  const [zoom, setZoom] = useState(1);

  // Multi-track state with volume/pan/mute/solo controls
  const [layers, setLayers] = useState([
    { 
      id: 1, 
      name: 'Track 1', 
      instrument: INSTRUMENTS[0], 
      notes: [], 
      color: TRACK_COLORS[0],
      volume: 0, // dB
      pan: 0,    // -1 to 1
      mute: false,
      solo: false,
      attack: 0.01,
      decay: 0.2,
      sustain: 0.6,
      release: 0.8,
      cutoff: 20000,
      resonance: 1,
      humanize: false
    }
  ]);
  const [isDashboardOpen, setIsDashboardOpen] = useState(false);
  const [isGuideOpen, setIsGuideOpen] = useState(false);
  const [isManualOpen, setIsManualOpen] = useState(false);
  const [activeLayerId, setActiveLayerId] = useState(1);
  const [rhythmMode, setRhythmMode] = useState('off');

  // Drum bus properties for Mixer
  const [rhythmVolume, setRhythmVolume] = useState(-6);
  const [rhythmMute, setRhythmMute] = useState(false);
  const [rhythmSolo, setRhythmSolo] = useState(false);

  // Mixer overlay state
  const [isMixerOpen, setIsMixerOpen] = useState(false);

  // Peak activity and keyboard highlights
  const [trackActivity, setTrackActivity] = useState({});
  const [activeKeys, setActiveKeys] = useState({});

  const activeLayer = layers.find(l => l.id === activeLayerId) || layers[0];
  const currentInstrument = activeLayer.instrument;

  const [isProfileOpen, setIsProfileOpen] = useState(false);
  const [currentUser, setCurrentUser] = useState(() => {
    try {
      const saved = localStorage.getItem('melody_sketcher_user');
      return saved ? JSON.parse(saved) : null;
    } catch {
      return null;
    }
  });

  const recordNotePlaced = useCallback(() => {
    setCurrentUser(prev => {
      if (!prev) return null;
      const updated = {
        ...prev,
        notesPlaced: (prev.notesPlaced || 0) + 1,
        xp: prev.xp + 10
      };
      let xp = updated.xp;
      let level = updated.level;
      while (xp >= level * 100 && level < 8) {
        xp -= level * 100;
        level += 1;
        showToast(`ÔÜí LEVEL UP! You are now Level ${level}!`, 'success');
      }
      const finalUser = { ...updated, xp, level };
      localStorage.setItem('melody_sketcher_user', JSON.stringify(finalUser));
      return finalUser;
    });
  }, [showToast]);

  const recordNotePlayed = useCallback(() => {
    setCurrentUser(prev => {
      if (!prev) return null;
      const updated = {
        ...prev,
        notesPlayed: (prev.notesPlayed || 0) + 1,
        xp: prev.xp + 5
      };
      let xp = updated.xp;
      let level = updated.level;
      while (xp >= level * 100 && level < 8) {
        xp -= level * 100;
        level += 1;
        showToast(`ÔÜí LEVEL UP! You are now Level ${level}!`, 'success');
      }
      const finalUser = { ...updated, xp, level };
      localStorage.setItem('melody_sketcher_user', JSON.stringify(finalUser));
      return finalUser;
    });
  }, [showToast]);

  const triggerExportMidi = () => {
    exportMidi();
    setCurrentUser(prev => {
      if (!prev) return null;
      const updated = { ...prev, xp: prev.xp + 50 };
      let xp = updated.xp;
      let level = updated.level;
      while (xp >= level * 100 && level < 8) {
        xp -= level * 100;
        level += 1;
        showToast(`ÔÜí LEVEL UP! You are now Level ${level}!`, 'success');
      }
      const finalUser = { ...updated, xp, level };
      localStorage.setItem('melody_sketcher_user', JSON.stringify(finalUser));
      return finalUser;
    });
    showToast("MIDI Exported! +50 XP rewarded.", "success");
  };

  const triggerExportWav = () => {
    exportWav();
    setCurrentUser(prev => {
      if (!prev) return null;
      const updated = { ...prev, xp: prev.xp + 50 };
      let xp = updated.xp;
      let level = updated.level;
      while (xp >= level * 100 && level < 8) {
        xp -= level * 100;
        level += 1;
        showToast(`ÔÜí LEVEL UP! You are now Level ${level}!`, 'success');
      }
      const finalUser = { ...updated, xp, level };
      localStorage.setItem('melody_sketcher_user', JSON.stringify(finalUser));
      return finalUser;
    });
    showToast("WAV Exported! +50 XP rewarded.", "success");
  };

  const setCurrentInstrument = (inst) => {
    setLayers(prev => prev.map(l => l.id === activeLayerId ? { ...l, instrument: inst } : l));
  };

  const setNotes = useCallback((newNotesOrFn) => {
    setLayers(prev => prev.map(l => {
      if (l.id === activeLayerId) {
        return { ...l, notes: typeof newNotesOrFn === 'function' ? newNotesOrFn(l.notes) : newNotesOrFn };
      }
      return l;
    }));
  }, [activeLayerId]);

  const BEAT_WIDTH = BASE_BEAT_WIDTH * zoom;
  const ROW_HEIGHT = BASE_ROW_HEIGHT * zoom;
  const totalTicks = barCount * 4 * GRID_SUBDIVISIONS;

  const [reverbLevel, setReverbLevel] = useState(0.4);
  const [delayLevel, setDelayLevel] = useState(0.2);
  const [distortionLevel, setDistortionLevel] = useState(0);
  const [chorusLevel, setChorusLevel] = useState(0);
  const [phaserLevel, setPhaserLevel] = useState(0);
  const [eqLowLevel, setEqLowLevel] = useState(0);
  const [eqMidLevel, setEqMidLevel] = useState(0);
  const [eqHighLevel, setEqHighLevel] = useState(0);
  const [playheadPosition, setPlayheadPosition] = useState(0);
  const playheadPositionRef = useRef(0);

  const [gamepadCursor, setGamepadCursor] = useState({ tick: 0, index: 36 });
  const [gamepadConnectedName, setGamepadConnectedName] = useState(null);
  const [isFxOpen, setIsFxOpen] = useState(false);
  const [isInstrumentMenuOpen, setIsInstrumentMenuOpen] = useState(false);
  const [viewMode, setViewMode] = useState('studio'); // 'studio' or 'stage'
  const [metronome, setMetronome] = useState(false);
  const [isIntroOpen, setIsIntroOpen] = useState(true);

  // Ref to prevent default clean states from overwriting saved workspace immediately
  const hasInitializedRef = useRef(false);

  // Undo/Redo composition state stacks (declared before restoreWorkspace to satisfy ESLint)
  const [history, setHistory] = useState([layers.map(l => ({ id: l.id, notes: l.notes }))]);
  const [historyIndex, setHistoryIndex] = useState(0);
  const isUndoRedoAction = useRef(false);

  const getCurrentWorkspaceData = useCallback(() => {
    return {
      themeId: currentTheme.id,
      bpm,
      masterVolume,
      barCount,
      layers: layers.map(l => ({
        id: l.id,
        name: l.name,
        instrument: { id: l.instrument.id },
        notes: l.notes,
        color: l.color,
        volume: l.volume,
        pan: l.pan,
        mute: l.mute,
        solo: l.solo,
        attack: l.attack,
        decay: l.decay,
        sustain: l.sustain,
        release: l.release,
        cutoff: l.cutoff,
        resonance: l.resonance,
        humanize: l.humanize
      })),
      activeLayerId,
      reverbLevel,
      delayLevel,
      distortionLevel,
      chorusLevel,
      phaserLevel,
      eqLowLevel,
      eqMidLevel,
      eqHighLevel
    };
  }, [layers, currentTheme, bpm, masterVolume, barCount, activeLayerId, reverbLevel, delayLevel, distortionLevel, chorusLevel, phaserLevel, eqLowLevel, eqMidLevel, eqHighLevel]);

  const restoreWorkspace = useCallback((saved) => {
    if (!saved) return;
    if (saved.bpm) setBpm(saved.bpm);
    if (typeof saved.masterVolume === 'number') setMasterVolume(saved.masterVolume);
    if (saved.barCount) setBarCount(saved.barCount);
    if (saved.layers && saved.layers.length > 0) {
      const mapped = saved.layers.map(l => {
        const instId = typeof l.instrument === 'object' ? l.instrument?.id : l.instrument;
        const inst = INSTRUMENTS.find(i => i.id === instId) || INSTRUMENTS[0];
        return {
          id: l.id || Math.random(),
          name: l.name || 'Track',
          instrument: inst,
          notes: Array.isArray(l.notes) ? l.notes : [],
          color: l.color || TRACK_COLORS[0],
          volume: typeof l.volume === 'number' ? l.volume : 0,
          pan: typeof l.pan === 'number' ? l.pan : 0,
          mute: typeof l.mute === 'boolean' ? l.mute : false,
          solo: typeof l.solo === 'boolean' ? l.solo : false,
          attack: typeof l.attack === 'number' ? l.attack : 0.01,
          decay: typeof l.decay === 'number' ? l.decay : 0.2,
          sustain: typeof l.sustain === 'number' ? l.sustain : 0.6,
          release: typeof l.release === 'number' ? l.release : 0.8,
          cutoff: typeof l.cutoff === 'number' ? l.cutoff : 20000,
          resonance: typeof l.resonance === 'number' ? l.resonance : 1,
          humanize: typeof l.humanize === 'boolean' ? l.humanize : false
        };
      });
      setLayers(mapped);
      setHistory([mapped.map(l => ({ id: l.id, notes: l.notes }))]);
      setHistoryIndex(0);
    }
    if (saved.activeLayerId) setActiveLayerId(saved.activeLayerId);
    if (typeof saved.reverbLevel === 'number') setReverbLevel(saved.reverbLevel);
    if (typeof saved.delayLevel === 'number') setDelayLevel(saved.delayLevel);
    if (typeof saved.distortionLevel === 'number') setDistortionLevel(saved.distortionLevel);
    if (typeof saved.chorusLevel === 'number') setChorusLevel(saved.chorusLevel);
    if (typeof saved.phaserLevel === 'number') setPhaserLevel(saved.phaserLevel);
    if (typeof saved.eqLowLevel === 'number') setEqLowLevel(saved.eqLowLevel);
    if (typeof saved.eqMidLevel === 'number') setEqMidLevel(saved.eqMidLevel);
    if (typeof saved.eqHighLevel === 'number') setEqHighLevel(saved.eqHighLevel);
  }, []);

  const handleLaunchStudio = async (shouldRestore = false) => {
    if (Tone.context.state !== 'running') {
      try {
        await Tone.start();
      } catch {
        console.error("Audio Context initialization failed");
      }
    }

    if (shouldRestore && savedWorkspace) {
      restoreWorkspace(savedWorkspace);
    } else {
      try {
        localStorage.removeItem('melody_sketcher_workspace');
      } catch {
        // Ignored
      }
    }

    hasInitializedRef.current = true;
    setIsIntroOpen(false);
  };



  // Sync workspace composition edits to local storage
  useEffect(() => {
    if (!hasInitializedRef.current) return;
    try {
      localStorage.setItem('melody_sketcher_workspace', JSON.stringify({
        themeId: currentTheme.id,
        bpm,
        masterVolume,
        barCount,
        layers: layers.map(l => ({
          id: l.id,
          name: l.name,
          instrument: { id: l.instrument.id },
          notes: l.notes,
          color: l.color,
          volume: l.volume,
          pan: l.pan,
          mute: l.mute,
          solo: l.solo,
          attack: l.attack,
          decay: l.decay,
          sustain: l.sustain,
          release: l.release,
          cutoff: l.cutoff,
          resonance: l.resonance,
          humanize: l.humanize
        })),
        activeLayerId,
        reverbLevel,
        delayLevel,
        distortionLevel,
        chorusLevel,
        phaserLevel,
        eqLowLevel,
        eqMidLevel,
        eqHighLevel
      }));
    } catch {
      // Ignored in private browsing
    }

    if (isUndoRedoAction.current) {
      isUndoRedoAction.current = false;
      return;
    }

    // Push new edit state to history stack
    const currentNotesState = layers.map(l => ({ id: l.id, notes: l.notes }));
    setHistory(prev => {
      const next = prev.slice(0, historyIndex + 1);
      return [...next, currentNotesState];
    });
    setHistoryIndex(prev => prev + 1);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [layers, currentTheme, bpm, masterVolume, barCount, activeLayerId, reverbLevel, delayLevel, distortionLevel, chorusLevel, phaserLevel, eqLowLevel, eqMidLevel, eqHighLevel]);

  const handleUndo = useCallback(() => {
    if (historyIndex > 0) {
      isUndoRedoAction.current = true;
      const prevNotesState = history[historyIndex - 1];
      setLayers(prev => prev.map(l => {
        const matched = prevNotesState.find(p => p.id === l.id);
        return matched ? { ...l, notes: matched.notes } : l;
      }));
      setHistoryIndex(historyIndex - 1);
    }
  }, [history, historyIndex, setLayers, setHistoryIndex]);

  const handleRedo = useCallback(() => {
    if (historyIndex < history.length - 1) {
      isUndoRedoAction.current = true;
      const nextNotesState = history[historyIndex + 1];
      setLayers(prev => prev.map(l => {
        const matched = nextNotesState.find(p => p.id === l.id);
        return matched ? { ...l, notes: matched.notes } : l;
      }));
      setHistoryIndex(historyIndex + 1);
    }
  }, [history, historyIndex, setLayers, setHistoryIndex]);

  const clearSketch = useCallback(() => {
    setLayers(prev => {
      const cleared = prev.map(l => ({ ...l, notes: [] }));
      setHistory([cleared.map(l => ({ id: l.id, notes: [] }))]);
      setHistoryIndex(0);
      return cleared;
    });
  }, [setHistory, setHistoryIndex]);

  // Audio Engine Hook integration
  const {
    synthsRef,
    analyserRef,
    kickRef,
    snareRef,
    hihatRef,
    crashRef,
    playNote,
    triggerAttack,
    triggerRelease
  } = useAudioEngine({
    layers,
    reverbLevel,
    delayLevel,
    distortionLevel,
    chorusLevel,
    phaserLevel,
    eqLowLevel,
    eqMidLevel,
    eqHighLevel,
    masterVolume,
    rhythmVolume,
    rhythmMute,
    rhythmSolo
  });

  // Audio Exporter Hook integration
  const {
    isExporting,
    exportProgress,
    handleMidiUpload,
    exportMidi,
    exportWav
  } = useAudioExport({
    layers,
    bpm,
    barCount,
    rhythmMode,
    rhythmMute,
    rhythmVolume,
    reverbLevel,
    delayLevel,
    distortionLevel,
    chorusLevel,
    phaserLevel,
    eqLowLevel,
    eqMidLevel,
    eqHighLevel,
    totalTicks,
    setBpm,
    setBarCount,
    setLayers,
    setActiveLayerId,
    showToast
  });

  // Interactive component references
  const containerRef = useRef(null);
  const pianoKeysRef = useRef(null);
  const canvasComponentRef = useRef(null);

  // Keyboard lights schedules
  const triggerKeyHighlight = useCallback((noteName, color) => {
    setActiveKeys(prev => ({ ...prev, [noteName]: color || true }));
    setTimeout(() => {
      setActiveKeys(prev => {
        const next = { ...prev };
        delete next[noteName];
        return next;
      });
    }, 250);
  }, []);

  // Paint a note
  const addNoteAt = useCallback((tick, index) => {
    if (Tone.context.state !== 'running') {
      Tone.start().catch(() => {});
    }
    setNotes(prev => {
      if (prev.some(n => n.tick === tick && n.index === index)) return prev;
      const note = ALL_NOTES[index];
      playNote(note.name, activeLayerId, '8n');
      return [...prev, { ...note, tick, index }];
    });
    setTrackActivity(prev => ({ ...prev, [activeLayerId]: Date.now() }));
    recordNotePlaced();
  }, [activeLayerId, setNotes, playNote, recordNotePlaced]);

  // Erase a note
  const eraseNoteAt = useCallback((tick, index) => {
    if (Tone.context.state !== 'running') {
      Tone.start().catch(() => {});
    }
    setNotes(prev => {
      const existing = prev.findIndex(n => n.tick === tick && n.index === index);
      if (existing !== -1) {
        const newNotes = [...prev];
        newNotes.splice(existing, 1);
        return newNotes;
      }
      return prev;
    });
  }, [setNotes]);

  // Clear all notes of the active track
  const clearActiveTrack = useCallback(() => {
    setNotes([]);
  }, [setNotes]);

  // Transpose all notes of the active track
  const transposeActiveTrack = useCallback((semitones) => {
    setNotes(prev => {
      return prev.map(note => {
        const newMidi = note.midi + semitones;
        if (newMidi >= 21 && newMidi <= 108) {
          const newIndex = 108 - newMidi;
          return {
            ...note,
            name: ALL_NOTES[newIndex].name,
            midi: newMidi,
            index: newIndex
          };
        }
        return note;
      });
    });
  }, [setNotes]);

  // QWERTY & sidebar playable auditions
  const playNoteForKeyboard = useCallback((noteName) => {
    playNote(noteName, activeLayerId, '8n');
    const layer = layers.find(l => l.id === activeLayerId);
    const layerColor = layer ? layer.color : '#ffffff';
    triggerKeyHighlight(noteName, layerColor);
    setTrackActivity(prev => ({ ...prev, [activeLayerId]: Date.now() }));
    recordNotePlayed();

    const noteObj = ALL_NOTES.find(n => n.name === noteName);
    if (noteObj) {
      const index = ALL_NOTES.indexOf(noteObj);
      if (canvasComponentRef.current) {
        canvasComponentRef.current.triggerHitParticle(index, activeLayerId);
      }

      // Record visual key painting immediately if recording!
      if (isRecording) {
        addNoteAt(playheadPositionRef.current, index);
        if (!isPlaying) {
          // Advance step in step recording
          const nextTick = (playheadPositionRef.current + 1) % totalTicks;
          playheadPositionRef.current = nextTick;
          setPlayheadPosition(nextTick);

          updatePlayheadDOM(nextTick);
        }
      }
    }
  }, [activeLayerId, isRecording, isPlaying, totalTicks, triggerKeyHighlight, playNote, addNoteAt, BEAT_WIDTH, layers, recordNotePlayed]);

  // Playback Toggle
  const togglePlay = useCallback(async () => {
    if (Tone.context.state !== 'running') await Tone.start();

    if (isPlaying) {
      Tone.Transport.stop();
      setIsPlaying(false);
      setPlayheadPosition(playheadPositionRef.current);
    } else {
      Tone.Transport.start();
      setIsPlaying(true);
    }
  }, [isPlaying]);

  // Seek by seconds
  const seekSeconds = useCallback(async (deltaSeconds) => {
    if (Tone.context.state !== 'running') await Tone.start();

    const currentTick = playheadPositionRef.current;
    const beatDuration = 60 / bpm;
    const currentTickSeconds = (currentTick / 4) * beatDuration;

    let targetSeconds = currentTickSeconds + deltaSeconds;
    const totalSeconds = (totalTicks / 4) * beatDuration;

    // Wrap around boundaries
    targetSeconds = (targetSeconds % totalSeconds + totalSeconds) % totalSeconds;

    Tone.Transport.seconds = targetSeconds;

    const targetTick = Math.round((targetSeconds / beatDuration) * 4) % totalTicks;
    playheadPositionRef.current = targetTick;
    setPlayheadPosition(targetTick);

    updatePlayheadDOM(targetTick);
  }, [bpm, totalTicks]);

  // Scrub Playhead directly to tick
  const scrubPlayhead = useCallback(async (tick) => {
    if (Tone.context.state !== 'running') await Tone.start();
    const targetTick = Math.max(0, Math.min(tick, totalTicks - 1));
    const beatDuration = 60 / bpm;
    const targetSeconds = (targetTick / 4) * beatDuration;

    Tone.Transport.seconds = targetSeconds;

    playheadPositionRef.current = targetTick;
    setPlayheadPosition(targetTick);

    updatePlayheadDOM(targetTick);
  }, [bpm, totalTicks]);

  // Keyboard QWERTY MIDI Hook
  useEffect(() => {
    const handleKeyDown = (e) => {
      if (e.repeat && !['ArrowLeft', 'ArrowRight'].includes(e.code)) return; // Allow arrow repeat for playhead scrubbing

      // Undo/Redo Hotkeys
      if ((e.ctrlKey || e.metaKey) && e.code === 'KeyZ') {
        e.preventDefault();
        if (e.shiftKey) {
          handleRedo();
        } else {
          handleUndo();
        }
        return;
      }
      if ((e.ctrlKey || e.metaKey) && e.code === 'KeyY') {
        e.preventDefault();
        handleRedo();
        return;
      }

      if (e.code === 'Space' && e.target.tagName !== 'INPUT') {
        e.preventDefault();
        togglePlay();
        return;
      }
      if (e.code === 'Escape') {
        setIsFxOpen(false);
        setIsInstrumentMenuOpen(false);
        setIsMixerOpen(false);
        setIsDashboardOpen(false);
        setIsManualOpen(false);
        setIsProfileOpen(false);
        return;
      }

      // Play QWERTY note or trigger actions if not typing in input
      if (e.target.tagName !== 'INPUT') {
        // Toggle Panels
        if (e.code === 'KeyQ') {
          e.preventDefault();
          setIsDashboardOpen(prev => !prev);
          setIsFxOpen(false);
          setIsMixerOpen(false);
          return;
        }
        if (e.code === 'KeyM') {
          e.preventDefault();
          setIsMixerOpen(prev => !prev);
          setIsDashboardOpen(false);
          return;
        }
        if (e.code === 'KeyX') {
          e.preventDefault();
          setIsFxOpen(prev => !prev);
          setIsDashboardOpen(false);
          return;
        }
        if (e.code === 'KeyR') {
          e.preventDefault();
          setMetronome(prev => !prev);
          return;
        }
        if (e.code === 'KeyN' || e.code === 'KeyV') {
          e.preventDefault();
          setViewMode(prev => prev === 'studio' ? 'stage' : 'studio');
          return;
        }

        // Track selections (Digit 1-9)
        if (e.code.startsWith('Digit')) {
          const num = parseInt(e.code.replace('Digit', ''), 10);
          if (num >= 1 && num <= 9) {
            const targetTrack = layersRef.current[num - 1];
            if (targetTrack) {
              e.preventDefault();
              setActiveLayerId(targetTrack.id);
            }
          }
        }

        // Playhead scrubbing (ArrowLeft/Right)
        if (e.code === 'ArrowRight') {
          e.preventDefault();
          const nextTick = (playheadPositionRef.current + 1) % totalTicksRef.current;
          scrubPlayhead(nextTick);
          return;
        }
        if (e.code === 'ArrowLeft') {
          e.preventDefault();
          const prevTick = (playheadPositionRef.current - 1 + totalTicksRef.current) % totalTicksRef.current;
          scrubPlayhead(prevTick);
          return;
        }

        // Tempo adjustment (ArrowUp/Down)
        if (e.code === 'ArrowUp') {
          e.preventDefault();
          setBpm(prev => Math.min(prev + 5, 240));
          return;
        }
        if (e.code === 'ArrowDown') {
          e.preventDefault();
          setBpm(prev => Math.max(prev - 5, 40));
          return;
        }

        const noteName = KEY_TO_NOTE[e.code];
        if (noteName) {
          e.preventDefault();
          playNoteForKeyboard(noteName);
        }
      }
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [togglePlay, playNoteForKeyboard, handleUndo, handleRedo, setMetronome, setViewMode, setActiveLayerId, setBpm, setPlayheadPosition, scrubPlayhead, setIsManualOpen, setIsProfileOpen]);

  // Keep stable refs to avoid canceling and rescheduling the Tone.js transport loop
  const rhythmModeRef = useRef(rhythmMode);
  const activeLayerIdRef = useRef(activeLayerId);
  const beatWidthRef = useRef(BEAT_WIDTH);
  const totalTicksRef = useRef(totalTicks);
  const viewModeRef = useRef(viewMode);
  const zoomRef = useRef(zoom);
  const activeKeysRef = useRef(activeKeys);
  const triggerKeyHighlightRef = useRef(triggerKeyHighlight);
  const isRecordingRef = useRef(isRecording);
  const addNoteAtRef = useRef(addNoteAt);
  const metronomeRef = useRef(metronome);
  const layersRef = useRef(layers);

  /* eslint-disable react-hooks/immutability */
  // Sync refs safely in commit phase (avoiding React 19 render-phase ref mutation warning)
  useEffect(() => {
    rhythmModeRef.current = rhythmMode;
    activeLayerIdRef.current = activeLayerId;
    beatWidthRef.current = BEAT_WIDTH;
    totalTicksRef.current = totalTicks;
    viewModeRef.current = viewMode;
    zoomRef.current = zoom;
    activeKeysRef.current = activeKeys;
    triggerKeyHighlightRef.current = triggerKeyHighlight;
    isRecordingRef.current = isRecording;
    addNoteAtRef.current = addNoteAt;
    metronomeRef.current = metronome;
    layersRef.current = layers;
  });
  /* eslint-enable react-hooks/immutability */

  // Helper to update playhead position and sheet progress shading directly in the DOM
  function updatePlayheadDOM(tick) {
    const bw = beatWidthRef.current;
    const playheadEl = document.getElementById('studio-playhead-line');
    if (playheadEl) {
      playheadEl.style.left = `${tick * bw}px`;
    }
    const shadeEl = document.getElementById('studio-playhead-shade');
    if (shadeEl) {
      shadeEl.style.width = `${tick * bw}px`;
    }
    const progressBarEl = document.getElementById('timeline-progress-bar');
    if (progressBarEl) {
      progressBarEl.style.width = `${(tick / totalTicksRef.current) * 100}%`;
    }
  }

  // Music-reactive border glow & scale pulse
  useEffect(() => {
    let animId;
    const run = () => {
      let volumeNorm = 0;
      if (isPlaying && analyserRef && analyserRef.current) {
        try {
          const data = analyserRef.current.getValue();
          let sum = 0;
          let count = 0;
          for (let i = 0; i < data.length; i++) {
            if (data[i] !== undefined && data[i] !== -Infinity) {
              sum += data[i];
              count++;
            }
          }
          const avgDb = count > 0 ? sum / count : -100;
          // Normalize to 0..1 (assuming -100 to 0dB range)
          volumeNorm = Math.max(0, (avgDb + 100) / 100);
        } catch (e) {
          // ignore
        }
      }

      const root = document.documentElement;
      if (root) {
        // Boost slightly for visual feedback
        const intensity = volumeNorm * 1.5;
        root.style.setProperty('--music-glow', `${intensity}`);
        // Subtle scale pulse (between 1.0 and 1.006)
        const scaleVal = 1 + Math.max(0, volumeNorm - 0.4) * 0.012;
        root.style.setProperty('--music-scale', `${scaleVal}`);
      }

      animId = requestAnimationFrame(run);
    };

    run();
    return () => {
      cancelAnimationFrame(animId);
    };
  }, [isPlaying, analyserRef]);

  const clickSynthRef = useRef(null);
  useEffect(() => {
    const clickSynth = new Tone.Synth({
      oscillator: { type: 'sine' },
      envelope: { attack: 0.001, decay: 0.05, sustain: 0, release: 0.05 }
    }).toDestination();
    clickSynth.volume.value = -24;
    clickSynthRef.current = clickSynth;
    return () => {
      clickSynth.dispose();
      clickSynthRef.current = null;
    };
  }, []);

  const tickIndexRef = useRef(new Map());
  const barDensityRef = useRef(new Map());

  // Optimize lookup maps creation
  useEffect(() => {
    const tickIndex = new Map();
    for (let i = 0; i < layers.length; i++) {
      const layer = layers[i];
      const lNotes = layer.notes;
      for (let j = 0; j < lNotes.length; j++) {
        const note = lNotes[j];
        if (!tickIndex.has(note.tick)) tickIndex.set(note.tick, []);
        tickIndex.get(note.tick).push({ 
          layerId: layer.id, 
          name: note.name, 
          tick: note.tick, 
          index: note.index 
        });
      }
    }

    const barDensity = new Map();
    tickIndex.forEach((notes, tick) => {
      const bar = Math.floor(tick / 16);
      barDensity.set(bar, (barDensity.get(bar) || 0) + notes.length);
    });

    tickIndexRef.current = tickIndex;
    barDensityRef.current = barDensity;
  }, [layers]);

  // Sync Transport BPM smoothly without canceling scheduled events
  useEffect(() => {
    Tone.Transport.bpm.value = bpm;
  }, [bpm]);

  // Sequencer loop (runs once, reads from refs)
  useEffect(() => {
    const repeat = (time) => {
      const currentTick = Math.round(Tone.Transport.getTicksAtTime(time) / (Tone.Transport.PPQ / TICKS_PER_BEAT)) % totalTicksRef.current;
      playheadPositionRef.current = currentTick;

      // Update Playhead elements directly in DOM for ultimate performance
      updatePlayheadDOM(currentTick);

      // --- Metronome click generator ---
      if (metronomeRef.current && Tone.Transport.state === 'started' && currentTick % 4 === 0) {
        const isDownbeat = currentTick % 16 === 0;
        if (clickSynthRef.current) {
          clickSynthRef.current.triggerAttackRelease(isDownbeat ? 1000 : 750, '32n', time);
        }
      }

      // --- Rhythm engine drum triggers ---
      const activeRhythmMode = rhythmModeRef.current;
      if (activeRhythmMode !== 'off') {
        const beatInBar = currentTick % 16;
        const currentBar = Math.floor(currentTick / 16);
        const density = barDensityRef.current.get(currentBar) || 0;
        const hasNotesHere = tickIndexRef.current.has(currentTick);
        const isBarStart = beatInBar === 0;

        let triggeredDrum = false;

        if (activeRhythmMode === 'auto') {
          const kickBeats = density > 8 ? [0, 3, 6, 8, 11, 14] : density > 4 ? [0, 6, 8, 14] : [0, 8];
          if (kickBeats.includes(beatInBar) && kickRef.current) {
            kickRef.current.triggerAttackRelease('C1', '8n', time);
            triggeredDrum = true;
          }
          if ((beatInBar === 4 || beatInBar === 12) && snareRef.current) {
            snareRef.current.triggerAttackRelease('16n', time);
            triggeredDrum = true;
          } else if (density > 10 && (beatInBar === 2 || beatInBar === 10) && snareRef.current) {
            snareRef.current.volume.value = -20;
            snareRef.current.triggerAttackRelease('32n', time);
            snareRef.current.volume.value = -10;
            triggeredDrum = true;
          }
          if (density > 6) {
            if (hihatRef.current) { hihatRef.current.triggerAttackRelease('32n', time); triggeredDrum = true; }
          } else if (density > 2) {
            if (beatInBar % 2 === 0 && hihatRef.current) { hihatRef.current.triggerAttackRelease('32n', time); triggeredDrum = true; }
          } else if (hasNotesHere) {
            if (hihatRef.current) { hihatRef.current.triggerAttackRelease('32n', time); triggeredDrum = true; }
          }
          if (isBarStart && density > 0 && !(barDensityRef.current.get(currentBar - 1) || 0) && crashRef.current) {
            crashRef.current.triggerAttackRelease('C4', '4n', time);
            triggeredDrum = true;
          }
        } else if (activeRhythmMode === 'four-floor') {
          if (beatInBar % 4 === 0 && kickRef.current) { kickRef.current.triggerAttackRelease('C1', '8n', time); triggeredDrum = true; }
          if ((beatInBar === 4 || beatInBar === 12) && snareRef.current) { snareRef.current.triggerAttackRelease('16n', time); triggeredDrum = true; }
          if (hihatRef.current) { hihatRef.current.triggerAttackRelease('32n', time); triggeredDrum = true; }
          if (isBarStart && crashRef.current && hasNotesHere) { crashRef.current.triggerAttackRelease('C4', '4n', time); triggeredDrum = true; }
        } else if (activeRhythmMode === 'boom-bap') {
          if ((beatInBar === 0 || beatInBar === 5 || beatInBar === 10) && kickRef.current) { kickRef.current.triggerAttackRelease('C1', '8n', time); triggeredDrum = true; }
          if ((beatInBar === 4 || beatInBar === 12) && snareRef.current) {
            snareRef.current.triggerAttackRelease('16n', time);
            triggeredDrum = true;
          }
          if (beatInBar % 2 === 0 && hihatRef.current) { hihatRef.current.triggerAttackRelease('32n', time); triggeredDrum = true; }
          if ((beatInBar === 6 || beatInBar === 14) && hihatRef.current) { hihatRef.current.triggerAttackRelease('8n', time); triggeredDrum = true; }
        } else if (activeRhythmMode === 'ballad') {
          if (beatInBar === 0 && kickRef.current) { kickRef.current.triggerAttackRelease('C1', '4n', time); triggeredDrum = true; }
          if (beatInBar === 8 && hasNotesHere && kickRef.current) { kickRef.current.triggerAttackRelease('C1', '4n', time); triggeredDrum = true; }
          if ((beatInBar === 4 || beatInBar === 12) && snareRef.current) {
            snareRef.current.volume.value = -16;
            snareRef.current.triggerAttackRelease('8n', time);
            snareRef.current.volume.value = -10;
            triggeredDrum = true;
          }
          if (beatInBar % 4 === 0 && hihatRef.current) { hihatRef.current.triggerAttackRelease('16n', time); triggeredDrum = true; }
        }

        if (triggeredDrum) {
          setTrackActivity(prev => ({ ...prev, rhythm: Date.now() }));
        }
      }

      // O(1) tick notes triggering
      const tickNotes = tickIndexRef.current.get(currentTick);
      if (tickNotes) {
        const byLayer = new Map();
        for (let i = 0; i < tickNotes.length; i++) {
          const tn = tickNotes[i];
          if (!byLayer.has(tn.layerId)) byLayer.set(tn.layerId, []);
          byLayer.get(tn.layerId).push(tn);
        }

        byLayer.forEach((notes, layerId) => {
          const synth = synthsRef.current[layerId];
          const layer = layersRef.current ? layersRef.current.find(l => l.id === layerId) : null;
          const layerColor = layer ? layer.color : '#ffffff';

          if (synth && !synth.disposed) {
            const uniqueNotes = [...new Set(notes.map(n => n.name))];
            try {
              if (layer && layer.humanize) {
                const randomTimeOffset = (Math.random() - 0.5) * 0.025;
                const randomVelocity = 0.65 + Math.random() * 0.35;
                synth.triggerAttackRelease(uniqueNotes, '8n', time + randomTimeOffset, randomVelocity);
              } else {
                synth.triggerAttackRelease(uniqueNotes, '8n', time);
              }
            } catch {
              // Ignore disposed nodes
            }
          }

          setTrackActivity(prev => ({ ...prev, [layerId]: Date.now() }));
          notes.forEach(n => {
            if (triggerKeyHighlightRef.current) triggerKeyHighlightRef.current(n.name, layerColor);
            if (canvasComponentRef.current) canvasComponentRef.current.triggerHitParticle(n.index, layerId);
          });

          if (layerId === activeLayerIdRef.current) {
            for (let k = 0; k < notes.length; k++) {
              if (canvasComponentRef.current) canvasComponentRef.current.triggerSparkle(notes[k].tick, notes[k].index);
            }
          }
        });
      }
    };

    Tone.Transport.scheduleRepeat(repeat, '16n');
    return () => {
      Tone.Transport.cancel();
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  // Web MIDI API controller integration for physical keyboards ("wing keyboards")
  useMidiKeyboard({
    activeLayerIdRef,
    isRecordingRef,
    playheadPositionRef,
    addNoteAtRef,
    triggerAttack,
    triggerRelease,
    setActiveKeys,
    setTrackActivity,
    canvasComponentRef
  });

  // Gamepad/Joystick API controller integration
  useGamepadController({
    gamepadCursor,
    setGamepadCursor,
    activeLayerId,
    setActiveLayerId,
    layers,
    setLayers,
    isRecording,
    setIsRecording,
    togglePlay,
    seekSeconds,
    handleUndo,
    handleRedo,
    addNoteAt,
    eraseNoteAt,
    totalTicks,
    setGamepadConnectedName
  });



  // Remove a track
  const removeLayer = (id, e) => {
    e.stopPropagation();
    if (layers.length <= 1) return;
    setLayers(prev => prev.filter(l => l.id !== id));
    if (activeLayerId === id) {
      const remainingLayer = layers.find(l => l.id !== id);
      if (remainingLayer) {
        setActiveLayerId(remainingLayer.id);
      }
    }
  };

  const fileInputRef = useRef(null);

  return (
    <div 
      className="flex flex-col fixed inset-0 overflow-hidden text-white font-['Outfit'] bg-[#020203] p-4 daw-outer-padding" 
      ref={containerRef}
      onPointerDown={() => {
        if (Tone.context.state !== 'running') {
          Tone.start().catch(err => console.warn("Failed to unlock AudioContext:", err));
        }
      }}
    >

      {/* Rainbow border wrapper */}
      <div className="flex-1 flex flex-col overflow-hidden rounded-[24px] p-[1.5px] rainbow-wrapper">
        {/* Outer DAW Floating Shell */}
        <div className="flex-1 flex flex-col overflow-hidden rounded-[23px] border border-white/[0.08] bg-zinc-950/20 backdrop-blur-3xl shadow-[0_24px_80px_rgba(0,0,0,0.85)] relative daw-shell">

      {/* CSS hardware accelerated peak decay and dynamic theme overrides */}
      <style>{`
        :root {
          --accent: ${currentTheme.color};
          --accent-glow: ${currentTheme.color}88;
          --glow-color: ${currentTheme.color};
        }
      `}</style>

      {/* Dynamic background ambient glow */}
      <div 
        className="absolute inset-0 pointer-events-none transition-all duration-[2000ms] z-0 opacity-40 blur-[150px]"
        style={{
          background: `radial-gradient(ellipse at 50% 30%, rgba(0, 240, 255, 0.08) 0%, rgba(255, 46, 147, 0.04) 50%, transparent 100%)`
        }}
      />

      {/* Hidden File Input for MIDI uploads */}
      <input 
        type="file" 
        accept=".mid,.midi" 
        ref={fileInputRef} 
        onChange={handleMidiUpload} 
        className="hidden" 
        style={{ display: 'none' }}
      />

      {/* Header bar section */}
      <HeaderBar 
        currentTheme={currentTheme}
        setCurrentTheme={setCurrentTheme}
        barCount={barCount}
        setBarCount={setBarCount}
        zoom={zoom}
        setZoom={setZoom}
        fileInputRef={fileInputRef}
        handleMidiUpload={handleMidiUpload}
        exportMidi={triggerExportMidi}
        exportWav={triggerExportWav}
        currentInstrument={currentInstrument}
        isInstrumentMenuOpen={isInstrumentMenuOpen}
        setIsInstrumentMenuOpen={setIsInstrumentMenuOpen}
        isFxOpen={isFxOpen}
        setIsFxOpen={setIsFxOpen}
        openIntro={() => setIsIntroOpen(true)}
        isDashboardOpen={isDashboardOpen}
        setIsDashboardOpen={setIsDashboardOpen}
        openGuide={() => setIsGuideOpen(true)}
        openManual={() => setIsManualOpen(true)}
        openProfile={() => setIsProfileOpen(true)}
        currentUser={currentUser}
      />

      <div className="flex-1 flex overflow-hidden relative">

        {/* Interactive Side Piano Roll (Studio mode only) */}
        {viewMode === 'studio' && (
          <PianoKeys 
            ref={pianoKeysRef}
            viewMode={viewMode}
            activeKeys={activeKeys}
            playNoteForKeyboard={playNoteForKeyboard}
            activeLayer={activeLayer}
            ROW_HEIGHT={ROW_HEIGHT}
          />
        )}

        {/* Modular Hardware Grid Canvas */}
        <div className="flex-1 flex flex-col overflow-hidden relative">
          <SequencerCanvas
            ref={canvasComponentRef}
            layers={layers}
            activeLayerId={activeLayerId}
            zoom={zoom}
            viewMode={viewMode}
            playheadPosition={playheadPosition}
            activeKeys={activeKeys}
            currentTheme={currentTheme}
            isPlaying={isPlaying}
            isRecording={isRecording}
            addNoteAt={addNoteAt}
            eraseNoteAt={eraseNoteAt}
            pianoKeysRef={pianoKeysRef}
            totalTicks={totalTicks}
            BEAT_WIDTH={BEAT_WIDTH}
            ROW_HEIGHT={ROW_HEIGHT}
            gamepadCursor={gamepadConnectedName ? gamepadCursor : null}
            scrubPlayhead={scrubPlayhead}
          />
          {/* Floating Mixer Console Console */}
          <AnimatePresence>
            {isMixerOpen && (
              <MixerConsole 
                layers={layers}
                setLayers={setLayers}
                activeLayerId={activeLayerId}
                setActiveLayerId={setActiveLayerId}
                rhythmVolume={rhythmVolume}
                setRhythmVolume={setRhythmVolume}
                rhythmMute={rhythmMute}
                setRhythmMute={setRhythmMute}
                rhythmSolo={rhythmSolo}
                setRhythmSolo={setRhythmSolo}
                masterVolume={masterVolume}
                setMasterVolume={setMasterVolume}
                trackActivity={trackActivity}
                currentTheme={currentTheme}
                setIsInstrumentMenuOpen={setIsInstrumentMenuOpen}
                closeConsole={() => setIsMixerOpen(false)}
              />
            )}
          </AnimatePresence>
        </div>

        {/* Floating Master Visualizer Side Strip */}
        <AnimatePresence>
          {isFxOpen && (
            <MasterFxPanel
              analyserRef={analyserRef}
              reverbLevel={reverbLevel}
              setReverbLevel={setReverbLevel}
              delayLevel={delayLevel}
              setDelayLevel={setDelayLevel}
              distortionLevel={distortionLevel}
              setDistortionLevel={setDistortionLevel}
              chorusLevel={chorusLevel}
              setChorusLevel={setChorusLevel}
              phaserLevel={phaserLevel}
              setPhaserLevel={setPhaserLevel}
              eqLowLevel={eqLowLevel}
              setEqLowLevel={setEqLowLevel}
              eqMidLevel={eqMidLevel}
              setEqMidLevel={setEqMidLevel}
              eqHighLevel={eqHighLevel}
              setEqHighLevel={setEqHighLevel}
              currentTheme={currentTheme}
              closePanel={() => setIsFxOpen(false)}
            />
          )}
        </AnimatePresence>

        {/* Studio Utilities Dashboard */}
        <AnimatePresence>
          {isDashboardOpen && (
            <StudioDashboard 
              activeLayer={activeLayer}
              setLayers={setLayers}
              currentTheme={currentTheme}
              setCurrentTheme={setCurrentTheme}
              customThemes={customThemes}
              setCustomThemes={setCustomThemes}
              closeDashboard={() => setIsDashboardOpen(false)}
            />
          )}
        </AnimatePresence>

        {/* Floating Instrument Selector Menu */}
        <AnimatePresence>
          {isInstrumentMenuOpen && (
            <InstrumentSelector
              currentInstrument={currentInstrument}
              setCurrentInstrument={setCurrentInstrument}
              currentTheme={currentTheme}
              closeMenu={() => setIsInstrumentMenuOpen(false)}
            />
          )}
        </AnimatePresence>
      </div>

      {/* Dynamic Multi-track tabs strip */}
      <TrackTabs 
        layers={layers}
        setLayers={setLayers}
        activeLayerId={activeLayerId}
        setActiveLayerId={setActiveLayerId}
        removeLayer={removeLayer}
        trackActivity={trackActivity}
        viewMode={viewMode}
        clearActiveTrack={clearActiveTrack}
        transposeActiveTrack={transposeActiveTrack}
      />

      <TransportBar 
        isPlaying={isPlaying}
        togglePlay={togglePlay}
        seekSeconds={seekSeconds}
        isRecording={isRecording}
        setIsRecording={setIsRecording}
        playheadPosition={playheadPosition}
        totalTicks={totalTicks}
        bpm={bpm}
        setBpm={setBpm}
        zoom={zoom}
        setZoom={setZoom}
        barCount={barCount}
        setBarCount={setBarCount}
        masterVolume={masterVolume}
        setMasterVolume={setMasterVolume}
        clearSketch={clearSketch}
        rhythmMode={rhythmMode}
        setRhythmMode={setRhythmMode}
        isFxOpen={isFxOpen}
        setIsFxOpen={setIsFxOpen}
        isMixerOpen={isMixerOpen}
        setIsMixerOpen={setIsMixerOpen}
        isInstrumentMenuOpen={isInstrumentMenuOpen}
        setIsInstrumentMenuOpen={setIsInstrumentMenuOpen}
        viewMode={viewMode}
        setViewMode={setViewMode}
        handleUndo={handleUndo}
        handleRedo={handleRedo}
        currentTheme={currentTheme}
        metronome={metronome}
        setMetronome={setMetronome}
        analyserRef={analyserRef}
      />

        </div>
      </div>

      {/* High-Fidelity Rendering Modal Overlay */}
      <AnimatePresence>
        {isExporting && (
          <motion.div 
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            className="absolute inset-0 z-[999] flex flex-col items-center justify-center gap-6"
            style={{ background: 'radial-gradient(ellipse at 50% 40%, rgba(10,5,25,0.95) 0%, rgba(2,2,4,0.97) 70%)' }}
          >
            <div className="relative w-24 h-24 flex items-center justify-center">
              <svg className="w-24 h-24 transform -rotate-90">
                <circle 
                  cx="48" cy="48" r="40" 
                  stroke="rgba(255,255,255,0.04)" strokeWidth="3" fill="none"
                />
                <motion.circle 
                  cx="48" cy="48" r="40" 
                  stroke={currentTheme.color} strokeWidth="3" fill="none"
                  strokeDasharray="251.2"
                  strokeLinecap="round"
                  animate={{ strokeDashoffset: 251.2 - (251.2 * exportProgress) }}
                  transition={{ ease: "easeOut", duration: 0.1 }}
                  style={{ filter: `drop-shadow(0 0 8px ${currentTheme.color}80)` }}
                />
              </svg>
              <div className="absolute text-base font-black tracking-wider text-white select-none tabular-nums">
                {Math.round(exportProgress * 100)}%
              </div>
            </div>
            <div className="flex flex-col items-center gap-1.5">
              <h3 className="text-[11px] font-bold uppercase tracking-[0.25em] text-white">Rendering Audio</h3>
              <p className="text-[9px] font-bold text-slate-500 uppercase tracking-widest">CD-quality stereo WAV</p>
            </div>
          </motion.div>
        )}
      </AnimatePresence>

      {/* Intro Welcome Screen User Guide Overlay */}
      <AnimatePresence>
        {isIntroOpen && (
          <IntroOverlay 
            launchStudio={() => handleLaunchStudio(false)} 
            hasSavedWorkspace={!!savedWorkspace}
            restoreLastSession={() => handleLaunchStudio(true)}
            currentTheme={currentTheme}
          />
        )}
      </AnimatePresence>


      {/* Interactive Guide */}
      <AnimatePresence>
        {isGuideOpen && (
          <InteractiveGuide 
            currentTheme={currentTheme}
            closeGuide={() => setIsGuideOpen(false)}
          />
        )}
      </AnimatePresence>

      {/* User Manual Modal */}
      <AnimatePresence>
        {isManualOpen && (
          <UserManual 
            onClose={() => setIsManualOpen(false)}
          />
        )}
      </AnimatePresence>

      {/* User Profile Modal */}
      <UserProfileModal
        isOpen={isProfileOpen}
        onClose={() => {
          setIsProfileOpen(false);
          try {
            const saved = localStorage.getItem('melody_sketcher_user');
            setCurrentUser(saved ? JSON.parse(saved) : null);
          } catch {}
        }}
        currentTheme={currentTheme}
        getCurrentWorkspaceData={getCurrentWorkspaceData}
        onLoadProjectData={(projData) => {
          restoreWorkspace(projData);
        }}
        showToast={showToast}
      />

      {/* Gamepad Connected Alert Toast */}
      <AnimatePresence>
        {gamepadConnectedName && (
          <motion.div
            initial={{ opacity: 0, y: 30, scale: 0.95 }}
            animate={{ opacity: 1, y: 0, scale: 1 }}
            exit={{ opacity: 0, y: 20, scale: 0.95 }}
            className="fixed bottom-6 right-6 z-55 flex items-center gap-3 px-5 py-3 rounded-2xl glass-gloss shadow-2xl border border-emerald-500/20"
          >
            <div className="w-2.5 h-2.5 rounded-full bg-emerald-500 animate-pulse shadow-[0_0_8px_#10b981]" />
            <div className="flex flex-col">
              <span className="text-[10px] font-bold text-slate-400 uppercase tracking-widest leading-none">Gamepad Active</span>
              <span className="text-[12px] font-black text-white mt-1 leading-none">
                {gamepadConnectedName.split('(')[0].trim() || 'Controller'}
              </span>
            </div>
          </motion.div>
        )}
      </AnimatePresence>

      {/* In-App Toast Notifications */}
      <ToastContainer toasts={toasts} dismissToast={dismissToast} />
    </div>
  );
}

import { forwardRef, useImperativeHandle, useRef, useEffect, useCallback } from 'react';
import { 
  NOTES_COUNT,
  ALL_NOTES,
  TICKS_PER_BEAT,
  NOTE_TO_KEY_LABEL
} from '../constants/midiConstants';
import * as Tone from 'tone';

const SequencerCanvas = forwardRef(({
  layers,
  activeLayerId,
  zoom,
  viewMode,
  playheadPosition,
  activeKeys,
  currentTheme,
  isPlaying,
  addNoteAt,
  eraseNoteAt,
  pianoKeysRef,
  totalTicks,
  BEAT_WIDTH,
  ROW_HEIGHT,
  gamepadCursor,
  scrubPlayhead
}, ref) => {
  const canvasRef = useRef(null);
  const scrollContainerRef = useRef(null);
  const rulerCanvasRef = useRef(null);

  const isDrawingRef = useRef(false);
  const isErasingRef = useRef(false);
  const isScrubbingRef = useRef(false);
  const lastDrawnNoteRef = useRef(null);

  const sparklesRef = useRef([]);
  const hitParticlesRef = useRef([]);
  const playheadPositionRef = useRef(playheadPosition);

  // Sync playhead position ref when prop changes (scrub, step-record, etc.)
  useEffect(() => {
    playheadPositionRef.current = playheadPosition;
  }, [playheadPosition]);

  // Real-time auto-scroll that tracks the live Tone.js playhead via requestAnimationFrame
  useEffect(() => {
    if (!isPlaying || viewMode !== 'studio') return;
    let scrollAnimId;
    let prevTick = -1;
    const scrollLoop = () => {
      scrollAnimId = requestAnimationFrame(scrollLoop);
      const container = scrollContainerRef.current;
      if (!container) return;

      // Read the real-time playhead from Tone.js transport
      let currentTick = playheadPositionRef.current;
      try {
        if (Tone.Transport.state === 'started') {
          const ticks = Tone.Transport.getTicksAtTime(Tone.now());
          currentTick = Math.round(ticks / (Tone.Transport.PPQ / TICKS_PER_BEAT)) % totalTicks;
          playheadPositionRef.current = currentTick;
        }
      } catch { /* ignore */ }

      if (currentTick === prevTick) return;
      prevTick = currentTick;

      const px = currentTick * BEAT_WIDTH;
      const scrollLeftVal = container.scrollLeft;
      const visibleWidth = container.clientWidth;

      // Auto-scroll when playhead goes beyond 75% of visible area
      if (px > scrollLeftVal + visibleWidth * 0.75) {
        container.scrollLeft = Math.max(0, px - visibleWidth * 0.25);
      } else if (px < scrollLeftVal) {
        // Jump back if it loops to the beginning
        container.scrollLeft = Math.max(0, px - visibleWidth * 0.15);
      }
    };
    scrollLoop();
    return () => cancelAnimationFrame(scrollAnimId);
  }, [isPlaying, viewMode, BEAT_WIDTH, totalTicks]);

  // Auto-scroll scroll container when gamepad cursor moves out of view
  useEffect(() => {
    if (!gamepadCursor || !scrollContainerRef.current) return;

    const container = scrollContainerRef.current;
    const cx = gamepadCursor.tick * BEAT_WIDTH;
    const cy = gamepadCursor.index * ROW_HEIGHT;
    const cw = BEAT_WIDTH;
    const ch = ROW_HEIGHT;

    const scrollLeftVal = container.scrollLeft;
    const scrollTopVal = container.scrollTop;
    const visibleWidth = container.clientWidth;
    const visibleHeight = container.clientHeight;

    // Horizontal check
    if (cx < scrollLeftVal + 40) {
      container.scrollLeft = Math.max(0, cx - 40);
    } else if (cx + cw > scrollLeftVal + visibleWidth - 40) {
      container.scrollLeft = cx + cw - visibleWidth + 40;
    }

    // Vertical check
    if (cy < scrollTopVal + 40) {
      container.scrollTop = Math.max(0, cy - 40);
    } else if (cy + ch > scrollTopVal + visibleHeight - 40) {
      container.scrollTop = cy + ch - visibleHeight + 40;
    }
  }, [gamepadCursor, BEAT_WIDTH, ROW_HEIGHT]);

  // Expose particle generators to parent
  useImperativeHandle(ref, () => ({
    triggerSparkle(tick, index) {
      const x = tick * BEAT_WIDTH + BEAT_WIDTH / 2;
      const y = index * ROW_HEIGHT + ROW_HEIGHT / 2;
      for (let i = 0; i < 5; i++) {
        sparklesRef.current.push({
          x: x + (Math.random() - 0.5) * 20,
          y: y + (Math.random() - 0.5) * 10,
          startTime: Date.now() + Math.random() * 200
        });
      }
    },
    triggerHitParticle(noteIndex, layerId) {
      if (viewMode !== 'stage' && viewMode !== 'stage-h') return;
      const canvas = canvasRef.current;
      if (!canvas) return;

      const width = canvas.width;
      const height = canvas.height;
      const layer = layers.find(l => l.id === layerId);
      const color = layer?.color || '#ffffff';

      let x, y;
      let vxBase = 0, vyBase = 0;
      let vxSpread = 0, vySpread = 0;

      if (viewMode === 'stage') {
        const KEY_WIDTH = width / NOTES_COUNT;
        const stageIndex = (ALL_NOTES.length - 1) - noteIndex;
        x = stageIndex * KEY_WIDTH + KEY_WIDTH / 2;
        y = height - 120; // PIANO_TOP
        vxSpread = 10;
        vyBase = -8;
        vySpread = 4;
      } else {
        const KEY_HEIGHT = height / NOTES_COUNT;
        x = 120; // PIANO_LEFT
        y = noteIndex * KEY_HEIGHT + KEY_HEIGHT / 2;
        vxBase = 8;
        vxSpread = 4;
        vySpread = 10;
      }

      // Create 16 particles for a gorgeous glass-shatter firework effect
      for (let i = 0; i < 16; i++) {
        const vx = vxBase !== 0 
          ? (Math.random() * vxSpread + vxBase) 
          : ((Math.random() - 0.5) * vxSpread);
        const vy = vyBase !== 0 
          ? (-Math.random() * vySpread + vyBase) 
          : ((Math.random() - 0.5) * vySpread);

        hitParticlesRef.current.push({
          x,
          y,
          vx,
          vy,
          size: Math.random() * 2 + 1,
          color,
          alpha: 1,
          life: 1.0,
          decay: Math.random() * 0.04 + 0.015
        });
      }

      // Ripple wave ring
      hitParticlesRef.current.push({
        x,
        y,
        isRipple: true,
        size: 4,
        maxSize: 45,
        color,
        alpha: 0.9,
        decay: 0.04
      });
    },
    getScrollContainer() {
      return scrollContainerRef.current;
    }
  }));

  // Sparkle generator helper
  const createSparkle = useCallback((tick, index) => {
    const x = tick * BEAT_WIDTH + BEAT_WIDTH / 2;
    const y = index * ROW_HEIGHT + ROW_HEIGHT / 2;
    for (let i = 0; i < 5; i++) {
      sparklesRef.current.push({
        x: x + (Math.random() - 0.5) * 20,
        y: y + (Math.random() - 0.5) * 10,
        startTime: Date.now() + Math.random() * 200
      });
    }
  }, [BEAT_WIDTH, ROW_HEIGHT]);

  // Draw the timeline ruler (bar numbers and beat markers)
  const drawRuler = useCallback(() => {
    const rulerCanvas = rulerCanvasRef.current;
    const container = scrollContainerRef.current;
    if (!rulerCanvas || !container || viewMode !== 'studio') return;

    const width = container.clientWidth;
    const RULER_H = 24;
    if (rulerCanvas.width !== width) rulerCanvas.width = width;
    if (rulerCanvas.height !== RULER_H) rulerCanvas.height = RULER_H;

    const ctx = rulerCanvas.getContext('2d');
    ctx.clearRect(0, 0, width, RULER_H);

    const scrollLeft = container.scrollLeft;
    const startTick = Math.max(0, Math.floor(scrollLeft / BEAT_WIDTH));
    const endTick = Math.min(totalTicks, Math.ceil((scrollLeft + width) / BEAT_WIDTH));

    // Background gradient
    ctx.fillStyle = 'rgba(0,0,0,0.55)';
    ctx.fillRect(0, 0, width, RULER_H);

    // Bottom border
    ctx.strokeStyle = 'rgba(255,255,255,0.08)';
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(0, RULER_H - 0.5);
    ctx.lineTo(width, RULER_H - 0.5);
    ctx.stroke();

    for (let i = startTick; i <= endTick; i++) {
      const x = i * BEAT_WIDTH - scrollLeft;
      const isBar = i % 4 === 0;
      const isBeat = i % 1 === 0;

      if (isBar) {
        // Bar line
        ctx.strokeStyle = 'rgba(255,255,255,0.25)';
        ctx.lineWidth = 1;
        ctx.beginPath();
        ctx.moveTo(x, 2);
        ctx.lineTo(x, RULER_H - 2);
        ctx.stroke();

        // Bar number
        ctx.fillStyle = 'rgba(255,255,255,0.6)';
        ctx.font = 'bold 9px Outfit, Inter, sans-serif';
        ctx.fillText(`${(i / 4) + 1}`, x + 4, 14);
      } else if (isBeat) {
        // Beat tick
        ctx.strokeStyle = 'rgba(255,255,255,0.1)';
        ctx.lineWidth = 0.5;
        ctx.beginPath();
        ctx.moveTo(x, RULER_H - 7);
        ctx.lineTo(x, RULER_H - 2);
        ctx.stroke();
      }
    }

    // Playhead marker on ruler
    const playheadX = playheadPositionRef.current * BEAT_WIDTH - scrollLeft;
    if (playheadX >= 0 && playheadX <= width) {
      ctx.fillStyle = currentTheme.color;
      ctx.shadowBlur = 6;
      ctx.shadowColor = currentTheme.color;
      ctx.beginPath();
      ctx.moveTo(playheadX - 4, RULER_H);
      ctx.lineTo(playheadX + 4, RULER_H);
      ctx.lineTo(playheadX, RULER_H - 6);
      ctx.closePath();
      ctx.fill();
      ctx.shadowBlur = 0;
    }
  }, [viewMode, BEAT_WIDTH, totalTicks, currentTheme]);

  // Redraw grid callback
  const drawGrid = useCallback(() => {
    const canvas = canvasRef.current;
    const container = scrollContainerRef.current;
    if (!canvas || !container) return;

    const clientWidth = container.clientWidth;
    const clientHeight = container.clientHeight;
    const activeLayer = layers.find(l => l.id === activeLayerId) || layers[0];

    if (viewMode === 'studio') {
      if (canvas.width !== clientWidth) canvas.width = clientWidth;
      if (canvas.height !== clientHeight) canvas.height = clientHeight;
    } else {
      const stageW = typeof window !== 'undefined' ? window.innerWidth : 1920;
      const stageH = typeof window !== 'undefined' ? window.innerHeight - 280 : 800;
      if (canvas.width !== stageW) canvas.width = stageW;
      if (canvas.height !== stageH) canvas.height = stageH;
    }

    const ctx = canvas.getContext('2d');
    const width = canvas.width;
    const height = canvas.height;

    const scrollLeft = container.scrollLeft;
    const scrollTop = container.scrollTop;

    const isStage = viewMode === 'stage' || viewMode === 'stage-h';
    const KEY_WIDTH = width / NOTES_COUNT;
    const KEY_HEIGHT = height / NOTES_COUNT;
    const STAGE_BEAT_HEIGHT = 60 * zoom;
    const STAGE_BEAT_WIDTH = 60 * zoom;
    const PIANO_HEIGHT = 120;
    const PIANO_LEFT = 120;
    const PIANO_TOP = height - PIANO_HEIGHT;

    // Viewport Culling limits
    let minX, maxX, minY, maxY;
    if (isStage) {
      if (viewMode === 'stage') {
        minX = 0; maxX = width;
        minY = 0; maxY = PIANO_TOP;
      } else {
        minX = PIANO_LEFT; maxX = width;
        minY = 0; maxY = height;
      }
    } else {
      minX = -BEAT_WIDTH * 2;
      maxX = clientWidth + BEAT_WIDTH * 2;
      minY = -ROW_HEIGHT * 2;
      maxY = clientHeight + ROW_HEIGHT * 2;
    }

    ctx.clearRect(0, 0, width, height);
    if (!isStage) {
      // Sleek obsidian backing for the grid
      ctx.fillStyle = '#050508';
      ctx.fillRect(0, 24, width, height - 24);
    } else {
      // Dark backdrop for stage modes
      ctx.fillStyle = '#030306';
      ctx.fillRect(0, 0, width, height);
    }

    if (!isStage) {
      const startTick = Math.max(0, Math.floor(scrollLeft / BEAT_WIDTH));
      const endTick = Math.min(totalTicks, Math.ceil((scrollLeft + clientWidth) / BEAT_WIDTH));

      // Studio grid rows
      for (let i = 0; i < ALL_NOTES.length; i++) {
        const note = ALL_NOTES[i];
        const y = i * ROW_HEIGHT + 24;
        if (y + ROW_HEIGHT < scrollTop || y > scrollTop + clientHeight) continue;

        const canvasY = y - scrollTop;
        const isC = note.name.startsWith('C') && !note.name.includes('#');
        if (isC) {
          ctx.fillStyle = 'rgba(255, 255, 255, 0.015)';
          ctx.fillRect(0, canvasY, clientWidth, ROW_HEIGHT);
        } else if (note.name.includes('#')) {
          ctx.fillStyle = 'rgba(0, 0, 0, 0.2)';
          ctx.fillRect(0, canvasY, clientWidth, ROW_HEIGHT);
        }

        ctx.strokeStyle = isC ? 'rgba(255, 255, 255, 0.15)' : 'rgba(255, 255, 255, 0.06)';
        ctx.lineWidth = isC ? 1.5 : 1;
        ctx.beginPath();
        ctx.moveTo(0, canvasY);
        ctx.lineTo(clientWidth, canvasY);
        ctx.stroke();
      }

      // Studio grid columns
      for (let i = startTick; i <= endTick; i++) {
        const x = i * BEAT_WIDTH;
        const canvasX = x - scrollLeft;
        const isBar = i % 4 === 0;
        ctx.strokeStyle = isBar ? 'rgba(255, 255, 255, 0.2)' : 'rgba(255, 255, 255, 0.04)';
        ctx.lineWidth = isBar ? 2 : 1;
        ctx.beginPath();
        ctx.moveTo(canvasX, 24);
        ctx.lineTo(canvasX, clientHeight);
        ctx.stroke();
      }
    } else {
      if (viewMode === 'stage') {
        // Stage Mode backdrop columns
        for (let i = 0; i < ALL_NOTES.length; i++) {
          const note = ALL_NOTES[i];
          const stageIndex = (ALL_NOTES.length - 1) - i;
          const x = stageIndex * KEY_WIDTH;
          const isSharp = note.name.includes('#');
          ctx.fillStyle = isSharp ? 'rgba(0,0,0,0.3)' : 'rgba(255,255,255,0.02)';
          ctx.fillRect(x, 0, KEY_WIDTH, PIANO_TOP);
          ctx.strokeStyle = 'rgba(255,255,255,0.04)';
          ctx.strokeRect(x, 0, KEY_WIDTH, PIANO_TOP);
        }
      } else {
        // Stage Horizontal backdrop rows
        for (let i = 0; i < ALL_NOTES.length; i++) {
          const note = ALL_NOTES[i];
          const y = i * KEY_HEIGHT;
          const isSharp = note.name.includes('#');
          ctx.fillStyle = isSharp ? 'rgba(0,0,0,0.3)' : 'rgba(255,255,255,0.02)';
          ctx.fillRect(PIANO_LEFT, y, width - PIANO_LEFT, KEY_HEIGHT);
          ctx.strokeStyle = 'rgba(255,255,255,0.04)';
          ctx.strokeRect(PIANO_LEFT, y, width - PIANO_LEFT, KEY_HEIGHT);
        }
      }

      // Light beams shooting up/across from active keys
      ctx.save();
      ctx.globalCompositeOperation = 'screen';
      for (let i = 0; i < ALL_NOTES.length; i++) {
        const note = ALL_NOTES[i];
        const isActive = activeKeys[note.name];
        if (isActive) {
          const beamColor = typeof isActive === 'string' ? isActive : (activeLayer.color || '#ffffff');

          if (viewMode === 'stage') {
            const stageIndex = (ALL_NOTES.length - 1) - i;
            const x = stageIndex * KEY_WIDTH;
            const gradient = ctx.createLinearGradient(x + KEY_WIDTH / 2, PIANO_TOP, x + KEY_WIDTH / 2, 0);
            gradient.addColorStop(0, `${beamColor}99`);
            gradient.addColorStop(0.4, `${beamColor}3d`);
            gradient.addColorStop(1, `${beamColor}00`);
            ctx.fillStyle = gradient;
            ctx.fillRect(x, 0, KEY_WIDTH, PIANO_TOP);

            // Add a beautiful neon flare splash at the bottom base on collision!
            const flare = ctx.createRadialGradient(x + KEY_WIDTH / 2, PIANO_TOP, 0, x + KEY_WIDTH / 2, PIANO_TOP, KEY_WIDTH * 1.5);
            flare.addColorStop(0, '#ffffff');
            flare.addColorStop(0.3, `${beamColor}cc`);
            flare.addColorStop(1, `${beamColor}00`);
            ctx.fillStyle = flare;
            ctx.beginPath();
            ctx.arc(x + KEY_WIDTH / 2, PIANO_TOP, KEY_WIDTH * 1.5, 0, Math.PI, true);
            ctx.fill();
          } else {
            // Stage Horizontal light beams
            const y = i * KEY_HEIGHT;
            const gradient = ctx.createLinearGradient(PIANO_LEFT, y + KEY_HEIGHT / 2, width, y + KEY_HEIGHT / 2);
            gradient.addColorStop(0, `${beamColor}99`);
            gradient.addColorStop(0.4, `${beamColor}3d`);
            gradient.addColorStop(1, `${beamColor}00`);
            ctx.fillStyle = gradient;
            ctx.fillRect(PIANO_LEFT, y, width - PIANO_LEFT, KEY_HEIGHT);

            // Add a beautiful neon flare splash on the left base on collision!
            const flare = ctx.createRadialGradient(PIANO_LEFT, y + KEY_HEIGHT / 2, 0, PIANO_LEFT, y + KEY_HEIGHT / 2, KEY_HEIGHT * 2.5);
            flare.addColorStop(0, '#ffffff');
            flare.addColorStop(0.3, `${beamColor}cc`);
            flare.addColorStop(1, `${beamColor}00`);
            ctx.fillStyle = flare;
            ctx.beginPath();
            ctx.arc(PIANO_LEFT, y + KEY_HEIGHT / 2, KEY_HEIGHT * 2.5, -Math.PI / 2, Math.PI / 2, false);
            ctx.fill();
          }
        }
      }
      ctx.restore();
    }

    // Render notes
    let visibleCount = 0;
    const activeVisibleNotes = [];
    ctx.lineWidth = 1;

    let realPlayhead = playheadPositionRef.current;
    if (isPlaying && Tone.Transport.state === 'started') {
      const ticks = Tone.Transport.getTicksAtTime(Tone.now());
      realPlayhead = (ticks / (Tone.Transport.PPQ / TICKS_PER_BEAT)) % totalTicks;
    }

    for (let l = 0; l < layers.length; l++) {
      const layer = layers[l];
      const isMain = layer.id === activeLayerId;
      const lNotes = layer.notes;
      const layerColor = layer.color || '#ffffff';

      for (let n = 0; n < lNotes.length; n++) {
        const note = lNotes[n];
        let nx, ny, nw, nh;

        if (isStage) {
          if (viewMode === 'stage') {
            const stageIndex = (ALL_NOTES.length - 1) - note.index;
            nx = stageIndex * KEY_WIDTH;

            // Fix wrap-around visually (if note is at tick 0 and playhead is at 127)
            let distance = note.tick - realPlayhead;
            if (distance < -totalTicks / 2) distance += totalTicks;

            ny = PIANO_TOP - distance * STAGE_BEAT_HEIGHT;
            nw = KEY_WIDTH - 2;
            nh = STAGE_BEAT_HEIGHT - 2;
          } else {
            // Stage Horizontal layout: notes scroll right-to-left
            ny = note.index * KEY_HEIGHT;

            let distance = note.tick - realPlayhead;
            if (distance < -totalTicks / 2) distance += totalTicks;

            nx = PIANO_LEFT + distance * STAGE_BEAT_WIDTH;
            nw = STAGE_BEAT_WIDTH - 2;
            nh = KEY_HEIGHT - 1;
          }
        } else {
          nx = note.tick * BEAT_WIDTH - scrollLeft;
          ny = note.index * ROW_HEIGHT - scrollTop + 24;
          nw = BEAT_WIDTH - 4;
          nh = ROW_HEIGHT - 4;
        }

        // Culling
        if (nx + nw >= minX && nx <= maxX && ny + nh >= minY && ny <= maxY) {
          if (isStage) {
            const isStageV = viewMode === 'stage';
            const isStriking = isStageV 
              ? (ny + nh >= PIANO_TOP - 15) && (ny + nh <= PIANO_TOP + 15)
              : (nx >= PIANO_LEFT - 15) && (nx <= PIANO_LEFT + 15);

            // Glowing trail trailing behind the note
            ctx.save();
            ctx.globalCompositeOperation = 'screen';
            if (isStageV) {
              const trailLen = nh * 4;
              const trailGradient = ctx.createLinearGradient(nx, ny, nx, ny - trailLen);
              trailGradient.addColorStop(0, `${layerColor}4d`);
              trailGradient.addColorStop(0.5, `${layerColor}1a`);
              trailGradient.addColorStop(1, `${layerColor}00`);
              ctx.fillStyle = trailGradient;
              ctx.fillRect(nx + 1.5, ny - trailLen, nw - 2, trailLen);
            } else {
              const trailLen = nw * 4;
              const trailGradient = ctx.createLinearGradient(nx + nw, ny, nx + nw + trailLen, ny);
              trailGradient.addColorStop(0, `${layerColor}4d`);
              trailGradient.addColorStop(0.5, `${layerColor}1a`);
              trailGradient.addColorStop(1, `${layerColor}00`);
              ctx.fillStyle = trailGradient;
              ctx.fillRect(nx + nw, ny + 0.5, trailLen, nh - 1);
            }
            ctx.restore();

            // Main Glass/Translucent fill
            ctx.save();
            const noteGradient = ctx.createLinearGradient(nx, ny, nx + nw, ny + nh);
            noteGradient.addColorStop(0, `${layerColor}99`); // Semi-transparent base
            noteGradient.addColorStop(1, `${layerColor}40`); // Deeper translucency at bottom
            ctx.fillStyle = noteGradient;

            ctx.shadowBlur = isMain ? 24 : 12;
            ctx.shadowColor = layerColor;

            ctx.beginPath();
            const rad = isStageV ? Math.min(6, nw / 2 - 1) : Math.min(3, nh / 2 - 0.5);
            ctx.roundRect(nx + 1, ny + 1, nw - 1, nh - 1, rad);
            ctx.fill();
            ctx.restore();

            // Glass diagonal glossy sheen
            ctx.fillStyle = 'rgba(255, 255, 255, 0.14)';
            ctx.beginPath();
            ctx.moveTo(nx + 1.5, ny + 1.5);
            ctx.lineTo(nx + nw * 0.55, ny + 1.5);
            ctx.lineTo(nx + nw * 0.25, ny + nh - 1.5);
            ctx.lineTo(nx + 1.5, ny + nh - 1.5);
            ctx.closePath();
            ctx.fill();

            // Prism Chromatic Aberration Stroke (refracting border)
            ctx.save();
            ctx.lineWidth = 1;
            ctx.globalCompositeOperation = 'screen';

            // Left boundary refraction (red-pink)
            ctx.strokeStyle = 'rgba(255, 46, 147, 0.5)';
            ctx.beginPath();
            ctx.roundRect(nx + 0.5, ny + 1, nw - 1, nh - 1, rad);
            ctx.stroke();

            // Right boundary refraction (cyan)
            ctx.strokeStyle = 'rgba(0, 240, 255, 0.5)';
            ctx.beginPath();
            ctx.roundRect(nx + 1.5, ny + 1, nw - 1, nh - 1, rad);
            ctx.stroke();

            // Solid center border
            ctx.strokeStyle = `${layerColor}cc`;
            ctx.beginPath();
            ctx.roundRect(nx + 1, ny + 1, nw - 1, nh - 1, rad);
            ctx.stroke();
            ctx.restore();

            // Impact scaling and explosion flare
            if (isStriking) {
              ctx.save();
              ctx.shadowBlur = 50;
              ctx.shadowColor = layerColor;

              // Scale slightly on impact
              ctx.fillStyle = '#ffffff';
              ctx.beginPath();
              ctx.roundRect(nx - 1, ny, nw + 3, nh, rad + 2);
              ctx.fill();

              // Draw white-hot energy core
              ctx.fillStyle = '#ffffff';
              ctx.shadowBlur = 20;
              ctx.shadowColor = '#ffffff';
              ctx.beginPath();
              ctx.roundRect(nx + 3, ny + 3, nw - 5, nh - 5, rad);
              ctx.fill();
              ctx.restore();
            } else {
              // Top rim highlight for 3D bevel effect
              ctx.fillStyle = 'rgba(255,255,255,0.9)';
              ctx.fillRect(nx + 3, ny + 2, nw - 5, 2);
            }

            if (isMain) {
              activeVisibleNotes.push({ ...note, nx, ny, nw, nh });
            }
            visibleCount++;
          } else if (isMain) {
            activeVisibleNotes.push({ ...note, nx, ny, nw, nh });
            visibleCount++;
          } else {
            ctx.fillStyle = `${layerColor}1a`;
            ctx.strokeStyle = `${layerColor}4d`;
            ctx.beginPath();
            ctx.roundRect(nx + 2, ny + 2, nw, nh, 4);
            ctx.fill();
            ctx.stroke();
          }
        }
      }
    }

    // Glowing shadows for active track (Studio Mode only)
    const isHeavyLoad = visibleCount > 200;
    const trackColor = activeLayer.color || '#ffffff';

    if (!isStage) {
      for (let i = 0; i < activeVisibleNotes.length; i++) {
        const note = activeVisibleNotes[i];
        const { nx, ny, nw, nh } = note;

        // Glow effect
        if (!isHeavyLoad) {
          ctx.shadowBlur = 14;
          ctx.shadowColor = trackColor;
        }

        // Translucent gradient fill
        const noteGrad = ctx.createLinearGradient(nx, ny, nx, ny + nh);
        noteGrad.addColorStop(0, `${trackColor}f0`);
        noteGrad.addColorStop(1, `${trackColor}b0`);
        ctx.fillStyle = noteGrad;

        ctx.beginPath();
        ctx.roundRect(nx + 1, ny + 1, nw, nh, 5);
        ctx.fill();
        ctx.shadowBlur = 0;

        // Diagonal glass sheen
        ctx.fillStyle = 'rgba(255, 255, 255, 0.12)';
        ctx.beginPath();
        ctx.moveTo(nx + 1.5, ny + 1.5);
        ctx.lineTo(nx + nw * 0.55, ny + 1.5);
        ctx.lineTo(nx + nw * 0.25, ny + nh - 1.5);
        ctx.lineTo(nx + 1.5, ny + nh - 1.5);
        ctx.closePath();
        ctx.fill();

        // White bezel rim highlight
        ctx.fillStyle = 'rgba(255, 255, 255, 0.45)';
        ctx.fillRect(nx + 2.5, ny + 1.5, nw - 4, 1.5);

        // Border stroke with Chromatic Aberration Refraction
        ctx.save();
        ctx.lineWidth = 1.2;
        ctx.globalCompositeOperation = 'screen';

        // Left boundary refraction (red-pink)
        ctx.strokeStyle = 'rgba(255, 46, 147, 0.55)';
        ctx.beginPath();
        ctx.roundRect(nx + 0.5, ny + 1, nw, nh, 5);
        ctx.stroke();

        // Right boundary refraction (cyan)
        ctx.strokeStyle = 'rgba(0, 240, 255, 0.55)';
        ctx.beginPath();
        ctx.roundRect(nx + 1.5, ny + 1, nw, nh, 5);
        ctx.stroke();

        // Solid center border
        ctx.strokeStyle = 'rgba(255, 255, 255, 0.35)';
        ctx.beginPath();
        ctx.roundRect(nx + 1, ny + 1, nw, nh, 5);
        ctx.stroke();
        ctx.restore();
      }

      // Sparkles animation (Studio)
      const now = Date.now();
      const activeSparkles = sparklesRef.current.filter(s => now - s.startTime < 1000);
      for (let si = 0; si < activeSparkles.length; si++) {
        const s = activeSparkles[si];
        const age = (now - s.startTime) / 1000;
        const opacity = 1 - age;
        const sx = s.x - scrollLeft + Math.sin(age * 10) * 10;
        const sy = s.y - scrollTop - age * 30 + 24;
        ctx.fillStyle = `rgba(255, 255, 255, ${opacity})`;
        ctx.beginPath();
        ctx.arc(sx, sy, 2 * (1 - age), 0, Math.PI * 2);
        ctx.fill();
      }
      sparklesRef.current = activeSparkles;

      // Gamepad Selector Cursor (Studio)
      if (gamepadCursor) {
        const cx = gamepadCursor.tick * BEAT_WIDTH - scrollLeft;
        const cy = gamepadCursor.index * ROW_HEIGHT - scrollTop + 24;
        const cw = BEAT_WIDTH;
        const ch = ROW_HEIGHT;

        if (cx + cw >= minX && cx <= maxX && cy + ch >= minY && cy <= maxY) {
          ctx.save();
          ctx.strokeStyle = '#ffffff';
          ctx.lineWidth = 2.5;
          ctx.setLineDash([4, 2]); // dashed neon cursor box
          ctx.shadowBlur = 15;
          ctx.shadowColor = currentTheme.color;

          ctx.beginPath();
          ctx.roundRect(cx + 1, cy + 1, cw - 2, ch - 2, 4);
          ctx.stroke();

          // Semi-transparent overlay with theme accent color
          ctx.fillStyle = `${currentTheme.color}25`;
          ctx.fill();
          ctx.restore();
        }
      }
    }

    // Piano keys & particles (Stage)
    if (isStage) {
      const isStageV = viewMode === 'stage';

      // White Keys
      for (let i = 0; i < ALL_NOTES.length; i++) {
        const note = ALL_NOTES[i];
        const isSharp = note.name.includes('#');
        const isActive = activeKeys[note.name];

        if (!isSharp) {
          const keyColor = isActive ? (typeof isActive === 'string' ? isActive : activeLayer.color) : '#ffffff';
          ctx.fillStyle = keyColor;
          ctx.beginPath();

          if (isStageV) {
            const stageIndex = (ALL_NOTES.length - 1) - i;
            const x = stageIndex * KEY_WIDTH;
            ctx.roundRect(x, PIANO_TOP, KEY_WIDTH, PIANO_HEIGHT, [0, 0, 6, 6]);
            ctx.fill();
            ctx.strokeStyle = '#000';
            ctx.lineWidth = 0.5;
            ctx.stroke();

            if (isActive) {
              const keyGlow = ctx.createLinearGradient(x, PIANO_TOP, x, PIANO_TOP + PIANO_HEIGHT);
              keyGlow.addColorStop(0, 'rgba(255,255,255,0.8)');
              keyGlow.addColorStop(0.3, `${keyColor}80`);
              keyGlow.addColorStop(1, `${keyColor}00`);
              ctx.fillStyle = keyGlow;
              ctx.fillRect(x, PIANO_TOP, KEY_WIDTH, PIANO_HEIGHT);
            } else {
              ctx.fillStyle = 'rgba(0,0,0,0.06)';
              ctx.fillRect(x, PIANO_TOP, KEY_WIDTH, 12);
            }

            // Draw note name inside white key (vertical layout)
            ctx.save();
            ctx.font = 'bold 8px sans-serif';
            ctx.fillStyle = isActive ? '#000000' : 'rgba(0,0,0,0.45)';
            ctx.textAlign = 'center';
            ctx.textBaseline = 'bottom';
            ctx.fillText(note.name, x + KEY_WIDTH / 2, PIANO_TOP + PIANO_HEIGHT - 12);

            // Draw QWERTY key label if any
            const keyLabel = NOTE_TO_KEY_LABEL[note.name];
            if (keyLabel) {
              ctx.font = '900 7px sans-serif';
              ctx.fillStyle = isActive ? 'rgba(0,0,0,0.65)' : 'rgba(0,0,0,0.22)';
              ctx.fillText(`[${keyLabel}]`, x + KEY_WIDTH / 2, PIANO_TOP + PIANO_HEIGHT - 3);
            }
            ctx.restore();
          } else {
            // Stage Horizontal white keys
            const y = i * KEY_HEIGHT;
            ctx.roundRect(0, y, PIANO_LEFT, KEY_HEIGHT, [0, 4, 4, 0]);
            ctx.fill();
            ctx.strokeStyle = '#000';
            ctx.lineWidth = 0.5;
            ctx.stroke();

            if (isActive) {
              const keyGlow = ctx.createLinearGradient(0, y, PIANO_LEFT, y);
              keyGlow.addColorStop(0, 'rgba(255,255,255,0.8)');
              keyGlow.addColorStop(0.3, `${keyColor}80`);
              keyGlow.addColorStop(1, `${keyColor}00`);
              ctx.fillStyle = keyGlow;
              ctx.fillRect(0, y, PIANO_LEFT, KEY_HEIGHT);
            } else {
              ctx.fillStyle = 'rgba(0,0,0,0.06)';
              ctx.fillRect(PIANO_LEFT - 12, y, 12, KEY_HEIGHT);
            }

            // Draw note name inside white key (horizontal layout)
            ctx.save();
            ctx.font = 'bold 8px sans-serif';
            ctx.fillStyle = isActive ? '#000000' : 'rgba(0,0,0,0.45)';
            ctx.textAlign = 'left';
            ctx.textBaseline = 'middle';
            ctx.fillText(note.name, 10, y + KEY_HEIGHT / 2);

            // Draw QWERTY key label if any
            const keyLabel = NOTE_TO_KEY_LABEL[note.name];
            if (keyLabel) {
              ctx.font = '900 8px sans-serif';
              ctx.fillStyle = isActive ? 'rgba(0,0,0,0.65)' : 'rgba(0,0,0,0.25)';
              ctx.fillText(`[${keyLabel}]`, PIANO_LEFT - 25, y + KEY_HEIGHT / 2);
            }
            ctx.restore();
          }
        }
      }

      // Black Keys
      for (let i = 0; i < ALL_NOTES.length; i++) {
        const note = ALL_NOTES[i];
        const isSharp = note.name.includes('#');

        if (isSharp) {
          const isActive = activeKeys[note.name];
          const keyColor = isActive ? (typeof isActive === 'string' ? isActive : activeLayer.color) : '#111115';
          ctx.fillStyle = keyColor;
          ctx.beginPath();

          if (isStageV) {
            const stageIndex = (ALL_NOTES.length - 1) - i;
            const x = stageIndex * KEY_WIDTH;
            ctx.roundRect(x, PIANO_TOP, KEY_WIDTH, PIANO_HEIGHT * 0.62, [0, 0, 4, 4]);
            ctx.fill();
            ctx.strokeStyle = '#000';
            ctx.stroke();

            if (isActive) {
              const keyGlow = ctx.createLinearGradient(x, PIANO_TOP, x, PIANO_TOP + PIANO_HEIGHT * 0.62);
              keyGlow.addColorStop(0, 'rgba(255,255,255,0.9)');
              keyGlow.addColorStop(0.4, `${keyColor}99`);
              keyGlow.addColorStop(1, `${keyColor}00`);
              ctx.fillStyle = keyGlow;
              ctx.fillRect(x, PIANO_TOP, KEY_WIDTH, PIANO_HEIGHT * 0.62);
            } else {
              ctx.fillStyle = 'rgba(255,255,255,0.08)';
              ctx.fillRect(x + 1, PIANO_TOP + 1, KEY_WIDTH - 2, 4);
            }

            // Draw note name inside black key (vertical layout)
            ctx.save();
            ctx.font = 'bold 7px sans-serif';
            ctx.fillStyle = isActive ? '#ffffff' : 'rgba(255,255,255,0.42)';
            ctx.textAlign = 'center';
            ctx.textBaseline = 'bottom';
            ctx.fillText(note.name, x + KEY_WIDTH / 2, PIANO_TOP + PIANO_HEIGHT * 0.62 - 10);

            // Draw QWERTY key label if any
            const keyLabel = NOTE_TO_KEY_LABEL[note.name];
            if (keyLabel) {
              ctx.font = '900 6.5px sans-serif';
              ctx.fillStyle = isActive ? 'rgba(255,255,255,0.75)' : 'rgba(255,255,255,0.22)';
              ctx.fillText(`[${keyLabel}]`, x + KEY_WIDTH / 2, PIANO_TOP + PIANO_HEIGHT * 0.62 - 2);
            }
            ctx.restore();
          } else {
            // Stage Horizontal black keys
            const y = i * KEY_HEIGHT;
            ctx.roundRect(0, y, PIANO_LEFT * 0.62, KEY_HEIGHT, [0, 3, 3, 0]);
            ctx.fill();
            ctx.strokeStyle = '#000';
            ctx.stroke();

            if (isActive) {
              const keyGlow = ctx.createLinearGradient(0, y, PIANO_LEFT * 0.62, y);
              keyGlow.addColorStop(0, 'rgba(255,255,255,0.9)');
              keyGlow.addColorStop(0.4, `${keyColor}99`);
              keyGlow.addColorStop(1, `${keyColor}00`);
              ctx.fillStyle = keyGlow;
              ctx.fillRect(0, y, PIANO_LEFT * 0.62, KEY_HEIGHT);
            } else {
              ctx.fillStyle = 'rgba(255,255,255,0.08)';
              ctx.fillRect(PIANO_LEFT * 0.62 - 4, y + 1, 4, KEY_HEIGHT - 2);
            }

            // Draw note name inside black key (horizontal layout)
            ctx.save();
            ctx.font = 'bold 7px sans-serif';
            ctx.fillStyle = isActive ? '#ffffff' : 'rgba(255,255,255,0.42)';
            ctx.textAlign = 'left';
            ctx.textBaseline = 'middle';
            ctx.fillText(note.name, 6, y + KEY_HEIGHT / 2);

            // Draw QWERTY key label if any
            const keyLabel = NOTE_TO_KEY_LABEL[note.name];
            if (keyLabel) {
              ctx.font = '900 7px sans-serif';
              ctx.fillStyle = isActive ? 'rgba(255,255,255,0.75)' : 'rgba(255,255,255,0.22)';
              ctx.fillText(`[${keyLabel}]`, PIANO_LEFT * 0.62 - 20, y + KEY_HEIGHT / 2);
            }
            ctx.restore();
          }
        }
      }

      // Hit particles
      const particles = hitParticlesRef.current;
      for (let i = particles.length - 1; i >= 0; i--) {
        const p = particles[i];
        p.alpha -= p.decay;
        if (p.alpha <= 0) {
          particles.splice(i, 1);
          continue;
        }

        ctx.save();
        ctx.globalAlpha = p.alpha;

        if (p.isRipple) {
          p.size += (p.maxSize - p.size) * 0.1;
          ctx.strokeStyle = p.color;
          ctx.lineWidth = 1.5;
          ctx.beginPath();
          ctx.arc(p.x, p.y, p.size, 0, Math.PI * 2);
          ctx.stroke();
        } else {
          p.x += p.vx;
          p.y += p.vy;
          p.vy += 0.18;
          ctx.fillStyle = p.color;
          ctx.shadowBlur = 10;
          ctx.shadowColor = p.color;
          ctx.beginPath();
          ctx.arc(p.x, p.y, p.size, 0, Math.PI * 2);
          ctx.fill();
        }
        ctx.restore();
      }
    }
  }, [layers, activeLayerId, viewMode, zoom, BEAT_WIDTH, ROW_HEIGHT, totalTicks, activeKeys, isPlaying, currentTheme.color, gamepadCursor]);

  // Pointer interactions
  const handlePointerDown = (e) => {
    if (viewMode === 'stage' || viewMode === 'stage-h') return;
    const container = scrollContainerRef.current;
    if (!container) return;
    const rect = canvasRef.current.getBoundingClientRect();
    const x = e.clientX - rect.left + container.scrollLeft;

    const clientY = e.clientY - rect.top;
    const RULER_H = 24;

    if (clientY < RULER_H) {
      isScrubbingRef.current = true;
      const tick = Math.floor(x / BEAT_WIDTH);
      if (tick >= 0 && tick < totalTicks) {
        scrubPlayhead?.(tick);
      }
      return;
    }

    const y = clientY - RULER_H + container.scrollTop;
    const tick = Math.floor(x / BEAT_WIDTH);
    const index = Math.floor(y / ROW_HEIGHT);

    if (tick < 0 || tick >= totalTicks || index < 0 || index >= NOTES_COUNT) return;

    if (e.button === 2) {
      isErasingRef.current = true;
      eraseNoteAt(tick, index);
    } else {
      isDrawingRef.current = true;
      addNoteAt(tick, index);
      createSparkle(tick, index);
    }
  };

  const handlePointerMove = (e) => {
    const container = scrollContainerRef.current;
    if (!container) return;
    const rect = canvasRef.current.getBoundingClientRect();
    const x = e.clientX - rect.left + container.scrollLeft;

    if (isScrubbingRef.current) {
      const tick = Math.floor(x / BEAT_WIDTH);
      if (tick >= 0 && tick < totalTicks) {
        scrubPlayhead?.(tick);
      }
      return;
    }

    if (!isDrawingRef.current && !isErasingRef.current) return;

    const clientY = e.clientY - rect.top;
    const RULER_H = 24;
    if (clientY < RULER_H) return;

    const y = clientY - RULER_H + container.scrollTop;
    const tick = Math.floor(x / BEAT_WIDTH);
    const index = Math.floor(y / ROW_HEIGHT);

    if (tick < 0 || tick >= totalTicks || index < 0 || index >= NOTES_COUNT) return;
    if (lastDrawnNoteRef.current?.tick === tick && lastDrawnNoteRef.current?.index === index) return;

    if (isErasingRef.current) {
      eraseNoteAt(tick, index);
    } else if (isDrawingRef.current) {
      addNoteAt(tick, index);
      createSparkle(tick, index);
    }
  };

  const handlePointerUp = () => {
    isDrawingRef.current = false;
    isErasingRef.current = false;
    isScrubbingRef.current = false;
    lastDrawnNoteRef.current = null;
  };

  // Global pointerup listener to prevent stuck drawing/scrubbing states if released outside grid
  useEffect(() => {
    const handleGlobalPointerUp = () => {
      isDrawingRef.current = false;
      isErasingRef.current = false;
      isScrubbingRef.current = false;
      lastDrawnNoteRef.current = null;
    };
    window.addEventListener('pointerup', handleGlobalPointerUp);
    window.addEventListener('pointercancel', handleGlobalPointerUp);
    return () => {
      window.removeEventListener('pointerup', handleGlobalPointerUp);
      window.removeEventListener('pointercancel', handleGlobalPointerUp);
    };
  }, []);

  // Ruler wheel scrubbing
  const handleRulerWheel = (e) => {
    e.preventDefault();
    const delta = Math.abs(e.deltaX) > Math.abs(e.deltaY) ? e.deltaX : e.deltaY;
    if (delta === 0) return;
    const direction = delta > 0 ? 1 : -1;
    const currentTick = playheadPositionRef.current;
    const nextTick = (currentTick + direction + totalTicks) % totalTicks;
    scrubPlayhead?.(nextTick);
  };

  // Scroll sync
  const handleScroll = () => {
    if (viewMode === 'studio') {
      if (pianoKeysRef.current && scrollContainerRef.current) {
        pianoKeysRef.current.scrollTop = scrollContainerRef.current.scrollTop;
      }
      drawGrid();
      drawRuler();
    }
  };

  // Redraw loops
  useEffect(() => {
    drawGrid();
    drawRuler();
    const handleResize = () => {
      drawGrid();
      drawRuler();
    };
    window.addEventListener('resize', handleResize);
    return () => {
      window.removeEventListener('resize', handleResize);
    };
  }, [drawGrid, drawRuler]);

  useEffect(() => {
    if (viewMode === 'stage' || viewMode === 'stage-h' || isPlaying) {
      let animationFrame;
      const render = () => {
        drawGrid();
        if (viewMode === 'studio') drawRuler();
        animationFrame = requestAnimationFrame(render);
      };
      render();
      return () => cancelAnimationFrame(animationFrame);
    } else {
      drawGrid();
      if (viewMode === 'studio') drawRuler();
      if (sparklesRef.current.length > 0) {
        let animationFrame;
        const render = () => {
          drawGrid();
          if (viewMode === 'studio') drawRuler();
          if (sparklesRef.current.length > 0) {
            animationFrame = requestAnimationFrame(render);
          }
        };
        render();
        return () => {
          if (animationFrame) cancelAnimationFrame(animationFrame);
        };
      }
    }
  }, [drawGrid, drawRuler, viewMode, isPlaying]);

  return (
    <div 
      className="flex-1 overflow-auto relative scrollbar-studio" 
      ref={scrollContainerRef}
      onScroll={handleScroll}
      onPointerDown={handlePointerDown}
      onPointerMove={handlePointerMove}
      onPointerUp={handlePointerUp}
      onContextMenu={(e) => e.preventDefault()}
    >
      <div 
        style={{ 
          width: `${totalTicks * BEAT_WIDTH}px`, 
          height: `${viewMode === 'studio' ? ALL_NOTES.length * ROW_HEIGHT + 24 : ALL_NOTES.length * ROW_HEIGHT}px` 
        }} 
        className="absolute top-0 left-0 pointer-events-none"
      />
      <div className="sticky top-0 left-0 z-0 h-0 w-full overflow-visible pointer-events-none">
        <canvas ref={canvasRef} className="absolute top-0 left-0 block cursor-crosshair pointer-events-auto" />
        {viewMode === 'studio' && (
          <canvas 
            ref={rulerCanvasRef} 
            className="absolute top-0 left-0 block z-20 cursor-ew-resize border-b border-white/[0.08] pointer-events-auto" 
            style={{ height: '24px' }} 
            onWheel={handleRulerWheel}
          />
        )}
      </div>

      {viewMode === 'studio' && (
        <>
          <div 
            id="studio-playhead-shade"
            className="absolute bottom-0 pointer-events-none z-[5]"
            style={{
              top: '24px',
              background: 'linear-gradient(90deg, rgba(255, 46, 147, 0.015) 0%, rgba(0, 240, 255, 0.05) 100%)',
              width: `${playheadPosition * BEAT_WIDTH}px`,
              left: 0
            }}
          />
          <div 
            id="studio-playhead-line"
            className="absolute bottom-0 w-[1.5px] pointer-events-none z-10"
            style={{
              top: '24px',
              background: 'linear-gradient(to bottom, #ffffff, #00f0ff)',
              boxShadow: '0 0 8px 1px #00f0ff',
              left: `${playheadPosition * BEAT_WIDTH}px`
            }}
          />
        </>
      )}
    </div>
  );
});

SequencerCanvas.displayName = 'SequencerCanvas';

