import { useState } from 'react';
import { motion } from 'framer-motion';
import { 
  Sliders, 
  Wand2, 
  BookOpen, 
  Palette, 
  X, 
  ChevronRight, 
  Sparkles,
  Music,
  Disc
} from 'lucide-react';
import { THEMES, ALL_NOTES } from '../constants/midiConstants';

const SCALES = {
  chromatic: { name: 'Chromatic (All)', notes: ['C', 'C#', 'D', 'D#', 'E', 'F', 'F#', 'G', 'G#', 'A', 'A#', 'B'] },
