const AUTOCLOSE_MS = 3000;

// ÔöÇÔöÇÔöÇ Single Toast Item ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ
function ToastItem({ toast, onDismiss }) {
  const config = TOAST_CONFIG[toast.type] || TOAST_CONFIG.info;
  const progressRef = useRef(null);

  useEffect(() => {
    // Trigger CSS animation after mount
    requestAnimationFrame(() => {
      if (progressRef.current) {
        progressRef.current.style.transform = 'scaleX(0)';
      }
    });
  }, []);

  return (
    <motion.div
      layout
      initial={{ opacity: 0, y: 40, scale: 0.85, filter: 'blur(8px)' }}
      animate={{ opacity: 1, y: 0, scale: 1, filter: 'blur(0px)' }}
      exit={{ opacity: 0, x: 80, scale: 0.9, filter: 'blur(4px)' }}
      transition={{ 
        type: 'spring', 
        stiffness: 400, 
        damping: 28,
        mass: 0.8 
      }}
      onClick={() => onDismiss(toast.id)}
      style={{
        background: `${config.gradient}, rgba(8, 8, 14, 0.88)`,
        border: `1px solid ${config.borderColor}`,
        boxShadow: `${config.glowColor}, 0 20px 50px rgba(0,0,0,0.6), inset 0 1px 0 rgba(255,255,255,0.08)`,
        backdropFilter: 'blur(24px) saturate(200%)',
        WebkitBackdropFilter: 'blur(24px) saturate(200%)',
        cursor: 'pointer',
        overflow: 'hidden',
        position: 'relative',
      }}
      className="rounded-2xl min-w-[320px] max-w-[480px]"
    >
      {/* Shimmer Effect */}
      <div style={{
        position: 'absolute',
        inset: 0,
        background: `linear-gradient(105deg, transparent 40%, ${config.accentColor}08 50%, transparent 60%)`,
        animation: 'toastShimmer 3s ease-in-out infinite',
        pointerEvents: 'none',
      }} />

      {/* Content */}
      <div style={{
        display: 'flex',
        alignItems: 'flex-start',
        gap: '14px',
        padding: '18px 22px 20px',
        position: 'relative',
        zIndex: 1,
      }}>
        {/* Icon Container */}
        <div style={{
          flexShrink: 0,
          width: 44,
          height: 44,
          borderRadius: 12,
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'center',
          background: `${config.accentColor}12`,
          border: `1px solid ${config.accentColor}20`,
          boxShadow: `0 0 20px ${config.accentColor}15`,
        }}>
          {config.icon}
        </div>

        {/* Text */}
        <div style={{ flex: 1, minWidth: 0 }}>
          <div style={{
            fontSize: 11,
            fontWeight: 700,
            textTransform: 'uppercase',
            letterSpacing: '0.12em',
            color: config.accentColor,
            marginBottom: 5,
            lineHeight: 1,
            fontFamily: "'Outfit', 'Inter', sans-serif",
          }}>
            {toast.type === 'success' ? 'Ô£ô Success' : 
             toast.type === 'error' ? 'Ô£ò Error' : 
             toast.type === 'warning' ? 'ÔÜá Warning' : 'Ôä╣ Info'}
          </div>
          <div style={{
            fontSize: 14,
            fontWeight: 500,
            color: '#e2e8f0',
            lineHeight: 1.45,
            fontFamily: "'Outfit', 'Inter', sans-serif",
            wordBreak: 'break-word',
          }}>
            {toast.message}
          </div>
        </div>

        {/* Close hint */}
        <div style={{
          flexShrink: 0,
          opacity: 0.3,
          fontSize: 16,
          lineHeight: 1,
          marginTop: 2,
          transition: 'opacity 0.2s',
        }}
          onMouseEnter={e => e.currentTarget.style.opacity = '0.7'}
          onMouseLeave={e => e.currentTarget.style.opacity = '0.3'}
        >
          ├ù
        </div>
      </div>

      {/* Auto-close progress bar */}
      <div style={{
        position: 'absolute',
        bottom: 0,
        left: 0,
        right: 0,
        height: 3,
        background: 'rgba(255,255,255,0.04)',
        overflow: 'hidden',
      }}>
        <div
          ref={progressRef}
          style={{
            height: '100%',
            background: config.progressColor,
            transformOrigin: 'left',
            transform: 'scaleX(1)',
            transition: `transform ${AUTOCLOSE_MS}ms linear`,
            boxShadow: `0 0 8px ${config.accentColor}60`,
          }}
        />
      </div>
    </motion.div>
  );
}

// ÔöÇÔöÇÔöÇ Toast Container ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ
export function ToastContainer({ toasts, dismissToast }) {
  return (
    <>
      {/* Inject shimmer keyframe */}
      <style>{`
        @keyframes toastShimmer {
          0%, 100% { transform: translateX(-100%); }
          50% { transform: translateX(100%); }
        }
      `}</style>
      <div style={{
        position: 'fixed',
        bottom: 80,
        right: 24,
        zIndex: 9999,
        display: 'flex',
        flexDirection: 'column-reverse',
        gap: 12,
        pointerEvents: 'none',
      }}>
        <AnimatePresence mode="popLayout">
          {toasts.map(toast => (
            <div key={toast.id} style={{ pointerEvents: 'auto' }}>
              <ToastItem toast={toast} onDismiss={dismissToast} />
            </div>
          ))}
        </AnimatePresence>
      </div>
    </>
  );
}

// ÔöÇÔöÇÔöÇ useToast Hook ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ
export function useToast() {
  const [toasts, setToasts] = useState([]);
  const idCounter = useRef(0);

  const dismissToast = useCallback((id) => {
    setToasts(prev => prev.filter(t => t.id !== id));
  }, []);

  const showToast = useCallback((message, type = 'info') => {
    const id = ++idCounter.current;
    setToasts(prev => [...prev, { id, message, type }]);

    // Auto-dismiss after 3 seconds
    setTimeout(() => {
      setToasts(prev => prev.filter(t => t.id !== id));
    }, AUTOCLOSE_MS);
  }, []);

  return { toasts, showToast, dismissToast };
}

